function progressBar(iteration, total, prefix = '', suffix = '', decimals = 1, length = 100, fill = '█', printEnd = '\r') {
    if (total <= 0) return;
    const percent = ((iteration / total) * 100).toFixed(decimals);
    const filledLength = Math.floor(length * iteration / total);
    const emptyLength = length - filledLength;
    const bar = fill.repeat(filledLength) + '-'.repeat(emptyLength);
    process.stdout.write(`\r${prefix} |${bar}| ${percent}% ${suffix}${printEnd}`);
    if (iteration === total) {
        process.stdout.write('\n');
    }
}

