function unwrap_model(model) {
    // モデルがラッパーかどうかを型名で判定
    const typeName = model.constructor.name;

    // ラッパーのリスト
    const wrappers = [
        'DataParallel',
        'DistributedDataParallel',
        'DeepSpeedEngine',
        'FSDP',
        'DDP'
    ];

    // ラッパーに該当する場合、内部のモジュールを取り出す
    if (wrappers.includes(typeName)) {
        // 内部モジュールへのアクセス方法を確認
        if (model.module) {
            return unwrap_model(model.module);
        }
        // DeepSpeedの場合はmodule属性
        if (model.module) {
            return unwrap_model(model.module);
        }
    }

    // ラッパーでない場合はそのまま返す
    return model;
}

