function separateQtranslateTaggedLangs(text) {
    const qtStart = '[:';
    const qtEnd = ']';
    const qtEndLen = qtEnd.length;
    const qtEndWithLangLen = qtEndLen + 2;
    const qtChunks = text.split(qtStart);
    const contentByLang = {};
    let commonTxtList = [];

    for (let c of qtChunks) {
        if (!c.trim()) continue;
        let lang = '';
        if (c.startsWith(qtEnd)) {
            c = c.slice(qtEndLen);
            if (!c.trim()) continue;
        } else if (c.slice(2, qtEndWithLangLen).startsWith(qtEnd)) {
            lang = c.slice(0, 2);
            c = c.slice(qtEndWithLangLen);
        }
        if (!lang) {
            commonTxtList.push(c);
            for (let l in contentByLang) {
                contentByLang[l].push(c);
            }
        } else {
            if (!contentByLang[lang]) {
                contentByLang[lang] = commonTxtList.slice();
            }
            contentByLang[lang].push(c);
        }
    }

    if (commonTxtList.length && Object.keys(contentByLang).length === 0) {
        contentByLang[''] = commonTxtList;
    }

    for (let l in contentByLang) {
        contentByLang[l] = contentByLang[l].join(' ');
    }
    return contentByLang;
}

