        if (!lang) {
            common_txt_list.push(c);
            for (let l in content_by_lang) {
                content_by_lang[l].push(c);
            }
        } else {
            if (!content_by_lang[lang]) {
                content_by_lang[lang] = [...common_txt_list];
            }
            content_by_lang[lang].push(c);
        }
    }

    if (common_txt_list.length > 0 && Object.keys(content_by_lang).length === 0) {
        content_by_lang[''] = common_txt_list;
    }

    for (let l in content_by_lang) {
        content_by_lang[l] = content_by_lang[l].join(' ');
    }

    return content_by_lang;
}

