説明文: 与えられたPython関数をJavaScriptに移植し、Tensor操作を簡易的な数値配列操作で再現します。

```javascript
function get_cdn_group(batch, num_classes, num_queries, class_embed, num_dn = 100, cls_noise_ratio = 0.5, box_noise_scale = 1.0, training = false) {
    // 簡易的なTensor風クラス（数値配列とdevice情報を持つ）
    class Tensor {
        constructor(data, shape, device = 'cpu') {
            this.data = data; // フラットな配列
            this.shape = shape;
            this.device = device;
        }
        static zeros(shape, device = 'cpu') {
            const size = shape.reduce((a, b) => a * b, 1);
            return new Tensor(new Array(size).fill(0), shape, device);
        }
        static ones(shape, device = 'cpu') {
            const size = shape.reduce((a, b) => a * b, 1);
            return new Tensor(new Array(size).fill(1), shape, device);
        }
        static rand(shape, device = 'cpu') {
            const size = shape.reduce((a, b) => a * b, 1);
            return new Tensor(Array.from({length: size}, () => Math.random()), shape, device);
        }
        static randint(low, high, shape, dtype = 'int64', device = 'cpu') {
            const size = shape.reduce((a, b) => a * b, 1);
            return new Tensor(Array.from({length: size}, () => Math.floor(Math.random() * (high - low)) + low), shape, device);
        }
        static arange(start, end, step = 1, device = 'cpu') {
            const data = [];
            for (let i = start; i < end; i += step) data.push(i);
            return new Tensor(data, [data.length], device);
        }
        static cat(tensors, dim = 0) {
            if (dim === 0) {
                const data = [];
                for (const t of tensors) data.push(...t.data);
                return new Tensor(data, [data.length], tensors[0].device);
            } else {
                throw new Error('dim not supported');
            }
        }
        static stack(tensors, dim = 0) {
            if (dim === 0) {
                const shape = [tensors.length, ...tensors[0].shape];
                const data = [];
                for (const t of tensors) data.push(...t.data);
                return new Tensor(data, shape, tensors[0].device);
            } else {
                throw new Error('dim not supported');
            }
        }
        repeat(n, dim = 0) {
            if (dim === 0) {
                const newData = [];
                for (let i = 0; i < n; i++) newData.push(...this.data);
                return new Tensor(newData, [this.shape[0] * n, ...this.shape.slice(1)], this.device);
            } else {
                throw new Error('dim not supported');
            }
        }
        view(shape) {
            return new Tensor(this.data, shape, this.device);
        }
        clone() {
            return new Tensor([...this.data], [...this.shape], this.device);
        }
        get(index) {
            // フラットインデックスでアクセス
            return this.data[index];
        }
        set(index, value) {
            this.data[index] = value;
        }
        to(device) {
            return new Tensor(this.data, this.shape, device);
        }
        cpu() {
            return new Tensor(this.data, this.shape, 'cpu');
        }
        split(sizes, dim = 0) {
            if (dim === 0) {
                const result = [];
                let offset = 0;
                for (const size of sizes) {
                    const data = this.data.slice(offset, offset + size);
                    result.push(new Tensor(data, [size, ...this.shape.slice(1)], this.device));
                    offset += size;
                }
                return result;
            } else {
                throw new Error('dim not supported');
            }
        }
        reshape(shape) {
            return new Tensor(this.data, shape, this.device);
        }
        // インデックス操作
        indexSelect(indices) {
            const data = indices.map(i => this.data[i]);
            return new Tensor(data, [indices.length, ...this.shape.slice(1)], this.device);
        }
        // スライス代入
        sliceAssign(start, end, valueTensor) {
            for (let i = start; i < end; i++) {
                this.data[i] = valueTensor.data[i - start];
            }
        }
    }

    // 簡易的なxywh2xyxyとxyxy2xywh
    function xywh2xyxy(bbox) {
        // bbox: [N, 4] フラット配列
        const N = bbox.shape[0];
        const data = [];
        for (let i = 0; i < N; i++) {
            const x = bbox.data[i * 4];
            const y = bbox.data[i * 4 + 1];
            const w = bbox.data[i * 4 + 2];
            const h = bbox.data[i * 4 + 3];
            data.push(x - w / 2, y - h / 2, x + w / 2, y + h / 2);
        }
        return new Tensor(data, [N, 4], bbox.device);
    }

    function xyxy2xywh(bbox) {
        const N = bbox.shape[0];
        const data = [];
        for (let i = 0; i < N; i++) {
            const x1 = bbox.data[i * 4];
            const y1 = bbox.data[i * 4 + 1];
            const x2 = bbox.data[i * 4 + 2];
            const y2 = bbox.data[i * 4 + 3];
            data.push((x1 + x2) / 2, (y1 + y2) / 2, x2 - x1, y2 - y1);
        }
        return new Tensor(data, [N, 4], bbox.device);
    }

    function inverse_sigmoid(x) {
        // x: [N, 4]
        const N = x.shape[0];
        const data = [];
        for (let i = 0; i < N * 4; i++) {
            const val = Math.max(Math.min(x.data[i], 1 - 1e-6), 1e-6);
            data.push(Math.log(val / (1 - val)));
        }
        return new Tensor(data, [N, 4], x.device);
    }

    // メイン処理
    if (!training || num_dn <= 0) {
        return [null, null, null, null];
    }

    const gt_groups = batch.gt_groups;
    const total_num = gt_groups.reduce((a, b) => a + b, 0);
    const max_nums = Math.max(...gt_groups);
    if (max_nums === 0) {
        return [null, null, null, null];
    }

    let num_group = Math.floor(num_dn / max_nums);
    num_group = num_group === 0 ? 1 : num_group;
    const bs = gt_groups.length;

    const gt_cls = batch.cls; // Tensor [total_num]
    const gt_bbox = batch.bboxes; // Tensor [total_num, 4]
    const b_idx = batch.batch_idx; // Tensor [total_num]

    // dn_cls = gt_cls.repeat(2 * num_group)
    const dn_cls = gt_cls.repeat(2 * num_group);
    // dn_bbox = gt_bbox.repeat(2 * num_group, 1)
    const dn_bbox = gt_bbox.repeat(2 * num_group, 1);
    // dn_b_idx = b_idx.repeat(2 * num_group).view(-1)
    const dn_b_idx = b_idx.repeat(2 * num_group).view([b_idx.shape[0] * 2 * num_group]);

    // neg_idx = torch.arange(total_num * num_group) + num_group * total_num
    const neg_idx = [];
    for (let i = 0; i < total_num * num_group; i++) neg_idx.push(i + num_group * total_num);

    // クラスノイズ
    if (cls_noise_ratio > 0) {
        const mask = [];
        for (let i = 0; i < dn_cls.shape[0]; i++) {
            mask.push(Math.random() < cls_noise_ratio * 0.5);
        }
        const idx = [];
        for (let i = 0; i < mask.length; i++) if (mask[i]) idx.push(i);
        for (const i of idx) {
            dn_cls.data[i] = Math.floor(Math.random() * num_classes);
        }
    }

    // ボックスノイズ
    if (box_noise_scale > 0) {
        let known_bbox = xywh2xyxy(dn_bbox);
        // diff = (dn_bbox[..., 2:] * 0.5).repeat(1, 2) * box_noise_scale
        const diff = [];
        for (let i = 0; i < dn_bbox.shape[0]; i++) {
            const w = dn_bbox.data[i * 4 + 2] * 0.5 * box_noise_scale;
            const h = dn_bbox.data[i * 4 + 3] * 0.5 * box_noise_scale;
            diff.push(w, h, w, h);
        }
        // rand_sign = torch.randint_like(dn_bbox, 0, 2) * 2.0 - 1.0
        const rand_sign = [];
        for (let i = 0; i < dn_bbox.data.length; i++) {
            rand_sign.push((Math.floor(Math.random() * 2) * 2) - 1);
        }
        // rand_part = torch.rand_like(dn_bbox)
        const rand_part = [];
        for (let i = 0; i < dn_bbox.data.length; i++) {
            rand_part.push(Math.random());
        }
        // rand_part[neg_idx] += 1.0
        for (const idx of neg_idx) {
            for (let j = 0; j < 4; j++) {
                rand_part[idx * 4 + j] += 1.0;
            }
        }
        // rand_part *= rand_sign
        for (let i = 0; i < rand_part.length; i++) {
            rand_part[i] *= rand_sign[i];
        }
        // known_bbox += rand_part * diff
        for (let i = 0; i < known_bbox.data.length; i++) {
            known_bbox.data[i] += rand_part[i] * diff[i];
        }
        // clip
        for (let i = 0; i < known_bbox.data.length; i++) {
            known_bbox.data[i] = Math.max(0, Math.min(1, known_bbox.data[i]));
        }
        // dn_bbox = xyxy2xywh(known_bbox)
        dn_bbox.data = xyxy2xywh(known_bbox).data;
        // dn_bbox = inverse_sigmoid(dn_bbox)
        const inv = inverse_sigmoid(dn_bbox);
        dn_bbox.data = inv.data;
    }

    num_dn = max_nums * 2 * num_group;

    // dn_cls_embed = class_embed[dn_cls]
    const dn_cls_embed = new Tensor([], [dn_cls.shape[0], class_embed.shape[1]], class_embed.device);
    for (let i = 0; i < dn_cls.shape[0]; i++) {
        const cls = dn_cls.data[i];
        for (let j = 0; j < class_embed.shape[1]; j++) {
            dn_cls_embed.data.push(class_embed.data[cls * class_embed.shape[1] + j]);
        }
    }

    // padding_cls = torch.zeros(bs, num_dn, embed_dim)
    const padding_cls = Tensor.zeros([bs, num_dn, class_embed.shape[1]], gt_cls.device);
    // padding_bbox = torch.zeros(bs, num_dn, 4)
    const padding_bbox = Tensor.zeros([bs, num_dn, 4], gt_bbox.device);

    // map_indices = torch.cat([torch.tensor(range(num)) for num in gt_groups])
    let map_indices = [];
    for (const num of gt_groups) {
        for (let i = 0; i < num; i++) map_indices.push(i);
    }

    // pos_idx = torch.stack([map_indices + max_nums * i for i in range(num_group)], dim=0)
    const pos_idx_list = [];
    for (let i = 0; i < num_group; i++) {
        pos_idx_list.push(map_indices.map(x => x + max_nums * i));
    }
    const pos_idx = pos_idx_list; // 2D配列

    // map_indices = torch.cat([map_indices + max_nums * i for i in range(2 * num_group)])
    let map_indices_full = [];
    for (let i = 0; i < 2 * num_group; i++) {
        map_indices_full.push(...map_indices.map(x => x + max_nums * i));
    }

    // padding_cls[dn_b_idx, map_indices] = dn_cls_embed
    for (let i = 0; i < dn_b_idx.shape[0]; i++) {
        const b = dn_b_idx.data[i];
        const m = map_indices_full[i];
        for (let j = 0; j < class_embed.shape[1]; j++) {
            padding_cls.data[b * num_dn * class_embed.shape[1] + m * class_embed.shape[1] + j] = dn_cls_embed.data[i * class_embed.shape[1] + j];
        }
    }

    // padding_bbox[dn_b_idx, map_indices] = dn_bbox
    for (let i = 0; i < dn_b_idx.shape[0]; i++) {
        const b = dn_b_idx.data[i];
        const m = map_indices_full[i];
        for (let j = 0; j < 4; j++) {
            padding_bbox.data[b * num_dn * 4 + m * 4 + j] = dn_bbox.data[i * 4 + j];
        }
    }

    // attn_mask
    const tgt_size = num_dn + num_queries;
    const attn_mask = new Tensor(new Array(tgt_size * tgt_size).fill(false), [tgt_size, tgt_size], gt_cls.device);
    // attn_mask[num_dn:, :num_dn] = True
    for (let i = num_dn; i < tgt_size; i++) {
        for (let j = 0; j < num_dn; j++) {
            attn_mask.data[i * tgt_size + j] = true;
        }
    }
    for (let i = 0; i < num_group; i++) {
        const start = max_nums * 2 * i;
        const end = max_nums * 2 * (i + 1);
        if (i === 0) {
            for (let r = start; r < end; r++) {
                for (let c = max_nums * 2 * (i + 1); c < num_dn; c++) {
                    attn_mask.data[r * tgt_size + c] = true;
                }
            }
        }
        if (i === num_group - 1) {
            for (let r = start; r < end; r++) {
                for (let c = 0; c < max_nums * i * 2; c++) {
                    attn_mask.data[r * tgt_size + c] = true;
                }
            }
        } else {
            for (let r = start; r < end; r++) {
                for (let c = max_nums * 2 * (i + 1); c < num_dn; c++) {
                    attn_mask.data[r * tgt_size + c] = true;
                }
                for (let c = 0; c < max_nums * 2 * i; c++) {
                    attn_mask.data[r * tgt_size + c] = true;
                }
            }
        }
    }

    // dn_meta
    const pos_idx_tensors = [];
    let offset = 0;
    for (const num of gt_groups) {
        const part = [];
        for (let i = 0; i < num_group; i++) {
            for (let j = 0; j < num; j++) {
                part.push(pos_idx[i][offset + j]);
            }
        }
        pos_idx_tensors.push(part);
        offset += num;
    }
    const dn_meta = {
        dn_pos_idx: pos_idx_tensors,
        dn_num_group: num_group,
        dn_num_split: [num_dn, num_queries]
    };

    return [padding_cls.to(class_embed.device), padding_bbox.to(class_embed.device), attn_mask.to(class_embed.device), dn_meta];
}
