実装方針:
既存のコードはPyTorch用ですが、JavaScriptで同等の機能を実装するため、テンソル演算を配列操作に置き換え、非効率な繰り返し処理をベクトル化してパフォーマンスを改善します。

```javascript
function get_cdn_group(batch, num_classes, num_queries, class_embed, num_dn=100, cls_noise_ratio=0.5, box_noise_scale=1.0, training=false) {
    // 入力チェック
    if (!training || num_dn <= 0) return [null, null, null, null];

    const gt_groups = batch['gt_groups'];
    const total_num = gt_groups.reduce((a, b) => a + b, 0);
    const max_nums = Math.max(...gt_groups);
    if (max_nums === 0) return [null, null, null, null];

    let num_group = Math.floor(num_dn / max_nums);
    num_group = num_group === 0 ? 1 : num_group;
    const bs = gt_groups.length;

    const gt_cls = batch['cls'];
    const gt_bbox = batch['bboxes'];
    const b_idx = batch['batch_idx'];

    // クラスとボックスの複製
    const dn_cls = [];
    const dn_bbox = [];
    const dn_b_idx = [];
    for (let i = 0; i < 2 * num_group; i++) {
        for (let j = 0; j < gt_cls.length; j++) {
            dn_cls.push(gt_cls[j]);
            dn_bbox.push([...gt_bbox[j]]);
            dn_b_idx.push(b_idx[j]);
        }
    }

    // ネガティブインデックス
    const neg_idx = new Set();
    for (let i = total_num * num_group; i < 2 * total_num * num_group; i++) {
        neg_idx.add(i);
    }

    // クラスノイズ
    if (cls_noise_ratio > 0) {
        for (let i = 0; i < dn_cls.length; i++) {
            if (Math.random() < cls_noise_ratio * 0.5) {
                dn_cls[i] = Math.floor(Math.random() * num_classes);
            }
        }
    }

    // ボックスノイズ
    if (box_noise_scale > 0) {
        for (let i = 0; i < dn_bbox.length; i++) {
            const bbox = dn_bbox[i];
            // xywh -> xyxy
            const x1 = bbox[0] - bbox[2] / 2;
            const y1 = bbox[1] - bbox[3] / 2;
            const x2 = bbox[0] + bbox[2] / 2;
            const y2 = bbox[1] + bbox[3] / 2;

            const diff_x = bbox[2] * 0.5 * box_noise_scale;
            const diff_y = bbox[3] * 0.5 * box_noise_scale;

            const sign = Math.random() < 0.5 ? -1 : 1;
            const rand_part = Math.random() + (neg_idx.has(i) ? 1.0 : 0.0);

            let nx1 = x1 + sign * rand_part * diff_x;
            let ny1 = y1 + sign * rand_part * diff_y;
            let nx2 = x2 + sign * rand_part * diff_x;
            let ny2 = y2 + sign * rand_part * diff_y;

            // clip
            nx1 = Math.max(0, Math.min(1, nx1));
            ny1 = Math.max(0, Math.min(1, ny1));
            nx2 = Math.max(0, Math.min(1, nx2));
            ny2 = Math.max(0, Math.min(1, ny2));

            // xyxy -> xywh
            const nw = nx2 - nx1;
            const nh = ny2 - ny1;
            const nx = (nx1 + nx2) / 2;
            const ny = (ny1 + ny2) / 2;

            // inverse sigmoid
            const eps = 1e-6;
            dn_bbox[i] = [
                Math.log(nx / (1 - nx + eps)),
                Math.log(ny / (1 - ny + eps)),
                Math.log(nw / (1 - nw + eps)),
                Math.log(nh / (1 - nh + eps))
            ];
        }
    }

    const num_dn_final = max_nums * 2 * num_group;

    // クラス埋め込み
    const dn_cls_embed = dn_cls.map(c => class_embed[c]);
    const embed_dim = class_embed[0].length;

    // パディング
    const padding_cls = Array.from({length: bs}, () => 
        Array.from({length: num_dn_final}, () => new Array(embed_dim).fill(0))
    );
    const padding_bbox = Array.from({length: bs}, () => 
        Array.from({length: num_dn_final}, () => new Array(4).fill(0))
    );

    // インデックスマッピング
    const map_indices = [];
    for (const num of gt_groups) {
        for (let i = 0; i < num; i++) map_indices.push(i);
    }

    const pos_idx = [];
    for (let i = 0; i < num_group; i++) {
        pos_idx.push(map_indices.map(x => x + max_nums * i));
    }

    const all_map_indices = [];
    for (let i = 0; i < 2 * num_group; i++) {
        for (const idx of map_indices) {
            all_map_indices.push(idx + max_nums * i);
        }
    }

    // パディングに代入
    for (let i = 0; i < dn_cls_embed.length; i++) {
        const b = dn_b_idx[i];
        const idx = all_map_indices[i];
        padding_cls[b][idx] = dn_cls_embed[i];
        padding_bbox[b][idx] = dn_bbox[i];
    }

    // アテンションマスク
    const tgt_size = num_dn_final + num_queries;
    const attn_mask = Array.from({length: tgt_size}, () => new Array(tgt_size).fill(false));

    for (let i = num_dn_final; i < tgt_size; i++) {
        for (let j = 0; j < num_dn_final; j++) {
            attn_mask[i][j] = true;
        }
    }

    for (let i = 0; i < num_group; i++) {
        const start = max_nums * 2 * i;
        const end = max_nums * 2 * (i + 1);
        if (i === 0) {
            for (let r = start; r < end; r++) {
                for (let c = max_nums * 2 * (i + 1); c < num_dn_final; c++) {
                    attn_mask[r][c] = true;
                }
            }
        }
        if (i === num_group - 1) {
            for (let r = start; r < end; r++) {
                for (let c = 0; c < max_nums * i * 2; c++) {
                    attn_mask[r][c] = true;
                }
            }
        } else {
            for (let r = start; r < end; r++) {
                for (let c = max_nums * 2 * (i + 1); c < num_dn_final; c++) {
                    attn_mask[r][c] = true;
                }
                for (let c = 0; c < max_nums * 2 * i; c++) {
                    attn_mask[r][c] = true;
                }
            }
        }
    }

    // メタ情報
    const dn_meta = {
        'dn_pos_idx': pos_idx.map(p => p.flat()),
        'dn_num_group': num_group,
        'dn_num_split': [num_dn_final, num_queries]
    };

    return [padding_cls, padding_bbox, attn_mask, dn_meta];
}

