```typescript
function _is_escaped(line: string, index: number): boolean {
    let nbackslashes = 0;
    for (let i = index - 1; i >= 0; i--) {
        if (line[i] === '\\') {
            nbackslashes++;
        } else {
            break;
        }
    }
    return nbackslashes % 2 === 1;
}

