```typescript
function isEscaped(arr: any[], str: string, index: number): boolean {
    // 指定インデックスが文字列範囲外ならfalse
    if (index < 0 || index >= str.length) return false;

    let backslashCount = 0;
    let i = index - 1;
    // 直前のバックスラッシュを数える
    while (i >= 0 && str[i] === '\\') {
        backslashCount++;
        i--;
    }
    // 偶数ならエスケープされていない（false）、奇数ならエスケープされている（true）
    return backslashCount % 2 === 1;
}

