function get(
    dict: any[],
    key: number,
    defaultVal: any = null,
    type?: (value: any) => any
): any {
    try {
        let rv = dict[key];
        if (type !== null && type !== undefined) {
            rv = type(rv);
        }
        return rv;
    } catch (e) {
        if (e instanceof RangeError || e instanceof TypeError || e instanceof Error) {
            return defaultVal;
        }
