実装方針: 事前にマッピングテーブルを構築し、文字列の先頭チェックを最適化して、ループ内の不要な処理を削減します。

```typescript
function _map_single_label(label_name: string): string {
    // 事前にマッピングテーブルを構築（キーを完全一致で検索できるように）
    const entityMappings: Record<string, [string, string]> = {
        'nam_liv': ['B-PER', 'I-PER'],
        'nam_loc': ['B-LOC', 'I-LOC'],
        'nam_org': ['B-ORG', 'I-ORG']
    };

    if (label_name === 'O') {
        return 'O';
    }

    // 先頭のプレフィックスを一度だけ取得
    const prefix = label_name.startsWith('B-') ? 'B-' : 
                   label_name.startsWith('I-') ? 'I-' : '';

    // プレフィックスが無い場合はOを返す
    if (prefix === '') {
        return 'O';
    }

    // エンティティ名を抽出（B-やI-を除いた部分）
    const entityName = label_name.substring(2);

    // マッピングテーブルから直接検索
    const mapping = entityMappings[entityName];
    if (mapping) {
        return prefix === 'B-' ? mapping[0] : mapping[1];
    }

    // マッピングに無い場合はMISCを返す
    return prefix === 'B-' ? 'B-MISC' : 'I-MISC';
}

