function categorizeUrlRisk(url: string): string {
    const URL_RISK_CATEGORIES: { [key: string]: { vendors?: string[], patterns?: string[] } } = {
        'benign': {
            'vendors': ['microsoft.com', 'w3.org', 'cdnjs.cloudflare.com', 'unpkg.com', 'jsdelivr.net']
        },
        'low': {
            'vendors': ['github.com', 'npmjs.com', 'gitlab.com', 'bitbucket.org']
        },
        'high': {
            'patterns': ['-', '_', 'dynamic', 'temp', 'tmp', 'redirect']
        }
    };

    let netlocLower: string;
    try {
        const parsed = new URL(url);
        netlocLower = parsed.hostname.toLowerCase();
    } catch {
        return 'unknown';
    }

    // benignチェック
    for (const benign of URL_RISK_CATEGORIES['benign']['vendors'] || []) {
        if (netlocLower.includes(benign)) {
            return 'benign';
        }
    }

    // lowチェック
    for (const vendor of URL_RISK_CATEGORIES['low']?.vendors || []) {
        if (netlocLower.includes(vendor)) {
            return 'low';
        }
    }

    // IPアドレスチェック
    if (/^\d+\.\d+\.\d+\.\d+/.test(netlocLower)) {
        return 'high';
    }

    // highパターンチェック
    for (const pattern of URL_RISK_CATEGORIES['high']?.patterns || []) {
        if (netlocLower.includes(pattern)) {
            return 'high';
        }
    }

    return 'medium';
}

