        "google.com", "googleapis.com", "gstatic.com", "android.com",
        "apple.com", "icloud.com", "amazon.com", "aws.amazon.com",
        "facebook.com", "twitter.com", "x.com", "instagram.com", "youtube.com"
    ];

    // 完全一致またはサブドメイン一致のチェック
    const isSubdomainOrExact = (domain: string, candidate: string): boolean => {
        return domain === candidate || domain.endsWith("." + candidate);
    };

    // 高リスク判定: 生のIPアドレス
    const ipPattern = /^(\d{1,3}\.){3}\d{1,3}$/;
    if (ipPattern.test(hostname)) {
        const parts = hostname.split('.').map(Number);
        if (parts.every(p => p >= 0 && p <= 255)) {
            return "high";
        }
    }

    // 高リスク判定: タイポスクワッティングパターン
    // よくあるタイポパターン: 文字の置換、追加、削除、入れ替え
    const commonDomains = ["google", "microsoft", "facebook", "amazon", "apple", "netflix", "youtube", "twitter", "instagram", "linkedin"];
    for (const common of commonDomains) {
        if (hostname.includes(common) && !hostname.includes(common + ".")) {
            // 完全一致でない場合、タイポの可能性
            if (hostname !== common + ".com" && hostname !== common + ".org" && hostname !== common + ".net") {
                // レーベンシュタイン距離が1-2の場合はタイポと判定
                const distance = levenshtein(hostname.split('.')[0], common);
                if (distance <= 2) {
                    return "high";
                }
            }
        }
    }

    // 高リスク判定: 動的ドメイン (ランダムな文字列パターン)
    const dynamicPattern = /^[a-z0-9]{10,}\.[a-z]{2,}$/;
    if (dynamicPattern.test(hostname) && !hostname.includes(".")) {
        // 単一のランダムな長い文字列は動的ドメインの可能性
        return "high";
    }

    // benign判定: Microsoft, W3C, 信頼できるCDN
    for (const domain of microsoftDomains) {
        if (isSubdomainOrExact(hostname, domain)) return "benign";
    }
    for (const domain of w3cDomains) {
        if (isSubdomainOrExact(hostname, domain)) return "benign";
    }
    for (const domain of trustedCdns) {
        if (isSubdomainOrExact(hostname, domain)) return "benign";
    }

    // low判定: 既知の優良ベンダー
    for (const domain of knownGoodVendors) {
        if (isSubdomainOrExact(hostname, domain)) return "low";
    }

    // medium判定: 未知のドメイン
    return "medium";
}

// レーベンシュタイン距離計算関数
function levenshtein(a: string, b: string): number {
    const m = a.length;
    const n = b.length;
    const dp: number[][] = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));
    for (let i = 0; i <= m; i++) dp[i][0] = i;
    for (let j = 0; j <= n; j++) dp[0][j] = j;
    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            dp[i][j] = Math.min(
                dp[i - 1][j] + 1,
                dp[i][j - 1] + 1,
                dp[i - 1][j - 1] + cost
            );
        }
    }
    return dp[m][n];
}

