public class Main {
    public static int[] convertToTuple(Object input) {
        if (input instanceof Integer) {
            int val = (Integer) input;
            return new int[]{val, val};
        } else if (input instanceof JSONArray) {
            JSONArray arr = (JSONArray) input;
            if (arr.length() != 2) {
                throw new IllegalArgumentException("ValueError: int_or_tuple must have exactly 2 elements");
            }
            int[] result = new int[2];
            for (int i = 0; i < 2; i++) {
                Object elem = arr.get(i);
                if (!(elem instanceof Integer)) {
                    throw new IllegalArgumentException("ValueError: elements must be integers");
                }
                result[i] = (Integer) elem;
            }
            return result;
        } else {
            throw new IllegalArgumentException("ValueError: int_or_tuple must be an integer or a list of 2 integers");
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine();
        try {
            JSONArray inputArray = new JSONArray(line);
            if (inputArray.length() != 1) {
                throw new IllegalArgumentException("ValueError: expected exactly one argument");
            }
            Object arg = inputArray.get(0);
            int[] result = convertToTuple(arg);
            JSONArray output = new JSONArray();
            for (int v : result) {
                output.put(v);
            }
            System.out.println(output.toString());
        } catch (Exception e) {
            System.out.println("null");
