        for (double[] row : result) {
            JSONArray rowArr = new JSONArray();
            for (double v : row) rowArr.put(v);
            out.put(rowArr);
        }
        System.out.println(out.toString());
    }

    // JSON配列を2次元double配列に変換
    static double[][] jsonTo2DArray(JSONArray arr) {
        int rows = arr.length();
        if (rows == 0) return new double[0][0];
        int cols = arr.getJSONArray(0).length();
        double[][] data = new double[rows][cols];
        for (int i = 0; i < rows; i++) {
            JSONArray row = arr.getJSONArray(i);
            for (int j = 0; j < cols; j++) {
                data[i][j] = row.getDouble(j);
            }
        }
        return data;
    }

    // downsample関数（2次元配列のみ対応、axis=0または1）
    static double[][] downsample(double[][] data, int n, int axis, String xvals) {
        if (n <= 1) return data;

        if (axis == 0) {
            int nPts = data.length / n;
            double[][] result = new double[nPts][data[0].length];
            for (int i = 0; i < nPts; i++) {
                for (int j = 0; j < data[0].length; j++) {
                    double sum = 0;
                    for (int k = 0; k < n; k++) {
                        sum += data[i * n + k][j];
                    }
                    result[i][j] = sum / n;
                }
            }
            return result;
        } else if (axis == 1) {
            int nPts = data[0].length / n;
            double[][] result = new double[data.length][nPts];
            for (int i = 0; i < data.length; i++) {
                for (int j = 0; j < nPts; j++) {
                    double sum = 0;
                    for (int k = 0; k < n; k++) {
                        sum += data[i][j * n + k];
                    }
                    result[i][j] = sum / n;
                }
            }
            return result;
        }
        return data;
    }
