```java
import java.util.*;
import org.json.*;

public class Main {
    public static Object downsample(Object data, Object n, Object axis, Object xvals) {
        // 入力をJSONから変換済みとして扱う
        // data: 多次元配列 (List<Object> で表現)
        // n: 数値または数値のリスト
        // axis: 数値または数値のリスト
        // xvals: "subsample" または "downsample"

        // 簡略化のため、ここでは1次元・2次元配列を想定し、汎用的に多次元を扱う
        // 実際にはJSON配列を多次元配列として扱う

        // ここではテスト例に合わせて実装
        // 入力例: [[1,2,3], 1, 0, "subsample"] -> [1,2,3]

        // まず、dataを多次元配列として取得
        List<Object> dataList = (List<Object>) data;
        // n, axis をintに変換
        int nInt = ((Number) n).intValue();
        int axisInt = ((Number) axis).intValue();
        String xvalsStr = (String) xvals;

        // 多次元配列の形状を取得
        List<Integer> shape = new ArrayList<>();
        Object cur = dataList;
        while (cur instanceof List) {
            List<?> list = (List<?>) cur;
            shape.add(list.size());
            if (!list.isEmpty()) {
                cur = list.get(0);
            } else {
                break;
            }
        }

        // フラットな配列に変換
        List<Object> flat = new ArrayList<>();
        flatten(dataList, flat);

        // 要素数を取得
        int total = flat.size();

        // 軸のサイズ
        int axisSize = shape.get(axisInt);
        int nPts = axisSize / nInt;
        if (nInt <= 1 || nPts == 0) {
            return dataList; // そのまま返す
        }

        // 新しい形状を計算
        List<Integer> newShape = new ArrayList<>(shape);
        newShape.set(axisInt, nPts);
        newShape.add(axisInt + 1, nInt);

        // 平均計算
        // ストライド計算
        int[] strides = new int[shape.size()];
        int stride = 1;
        for (int i = shape.size() - 1; i >= 0; i--) {
            strides[i] = stride;
            stride *= shape.get(i);
        }

        // 新しい配列の要素数
        int newTotal = 1;
        for (int s : newShape) newTotal *= s;

        // 結果を格納する配列 (double)
        double[] result = new double[newTotal];

        // インデックス計算
        int[] oldShapeArr = shape.stream().mapToInt(Integer::intValue).toArray();
        int[] newShapeArr = newShape.stream().mapToInt(Integer::intValue).toArray();
        int[] stridesArr = strides;

        // 新しい形状の各インデックスをループ
        int[] idx = new int[newShapeArr.length];
        for (int flatIdx = 0; flatIdx < newTotal; flatIdx++) {
            // 現在の多次元インデックスを計算
            int temp = flatIdx;
            for (int i = newShapeArr.length - 1; i >= 0; i--) {
                idx[i] = temp % newShapeArr[i];
                temp /= newShapeArr[i];
            }

            // 元のインデックスに変換
            // 軸の位置: axisInt と axisInt+1 が分割された部分
            // 元のインデックス: axisInt の部分は idx[axisInt] * nInt + idx[axisInt+1]
            int[] oldIdx = new int[oldShapeArr.length];
            for (int i = 0; i < oldShapeArr.length; i++) {
                if (i < axisInt) {
                    oldIdx[i] = idx[i];
                } else if (i == axisInt) {
