```java
import java.util.*;
import java.lang.reflect.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();
        // JSON配列をパース（簡易実装）
        List<Object> argsList = parseJsonArray(input);
        int n = ((Number) argsList.get(0)).intValue();
        Object value = argsList.get(1);

        List<Integer> result = convertToPositiveInts(n, value);
        System.out.println(toJson(result));
    }

    // 簡易JSON配列パーサー（数値、文字列、配列、null、真偽値のみ対応）
    private static List<Object> parseJsonArray(String json) {
        json = json.trim();
        if (!json.startsWith("[") || !json.endsWith("]")) {
            throw new IllegalArgumentException("Invalid JSON array");
        }
        String content = json.substring(1, json.length() - 1).trim();
        List<Object> list = new ArrayList<>();
        if (content.isEmpty()) return list;

        int i = 0;
        while (i < content.length()) {
            char c = content.charAt(i);
            if (c == '[') {
                // 再帰的に配列をパース
                int depth = 1;
                int j = i + 1;
                while (j < content.length() && depth > 0) {
                    if (content.charAt(j) == '[') depth++;
                    else if (content.charAt(j) == ']') depth--;
                    j++;
                }
                String sub = content.substring(i, j);
                list.add(parseJsonArray(sub));
                i = j;
            } else if (c == '"') {
                // 文字列
                int j = i + 1;
                StringBuilder sb = new StringBuilder();
                while (j < content.length() && content.charAt(j) != '"') {
                    if (content.charAt(j) == '\\' && j + 1 < content.length()) {
                        sb.append(content.charAt(j + 1));
                        j += 2;
                    } else {
                        sb.append(content.charAt(j));
                        j++;
                    }
                }
                list.add(sb.toString());
                i = j + 1;
            } else if (Character.isDigit(c) || c == '-') {
                int j = i;
                while (j < content.length() && (Character.isDigit(content.charAt(j)) || content.charAt(j) == '.' || content.charAt(j) == '-')) {
                    j++;
                }
                String numStr = content.substring(i, j);
                try {
                    if (numStr.contains(".")) {
                        list.add(Double.parseDouble(numStr));
                    } else {
                        list.add(Long.parseLong(numStr));
                    }
                } catch (NumberFormatException e) {
                    throw new IllegalArgumentException("Invalid number");
                }
                i = j;
            } else if (c == 't' && content.startsWith("true", i)) {
                list.add(true);
                i += 4;
            } else if (c == 'f' && content.startsWith("false", i)) {
                list.add(false);
                i += 5;
            } else if (c == 'n' && content.startsWith("null", i)) {
                list.add(null);
                i += 4;
            } else if (c == ',' || c == ' ') {
                i++;
            } else {
                throw new IllegalArgumentException("Unexpected character: " + c);
            }
            // カンマをスキップ
            while (i < content.length() && (content.charAt(i) == ',' || content.charAt(i) == ' ')) {
                i++;
            }
        }
        return list;
    }

    // 簡易JSONシリアライザー
    private static String toJson(Object obj) {
        if (obj == null) return "null";
        if (obj instanceof Boolean) return obj.toString();
        if (obj instanceof Number) return obj.toString();
        if (obj instanceof String) return "\"" + obj + "\"";
        if (obj instanceof List) {
            StringBuilder sb = new StringBuilder("[");
            List<?> list = (List<?>) obj;
            for (int i = 0; i < list.size(); i++) {
                if (i > 0) sb.append(",");
                sb.append(toJson(list.get(i)));
            }
            sb.append("]");
            return sb.toString();
        }
        if (obj instanceof Map) {
            StringBuilder sb = new StringBuilder("{");
            Map<?, ?> map = (Map<?, ?>) obj;
            int i = 0;
            for (Map.Entry<?, ?> e : map.entrySet()) {
                if (i++ > 0) sb.append(",");
                sb.append("\"").append(e.getKey()).append("\":").append(toJson(e.getValue()));
            }
            sb.append("}");
            return sb.toString();
        }
        return "\"" + obj.toString() + "\"";
    }

    // メインの変換関数
    public static List<Integer> convertToPositiveInts(int n, Object value) {
        // nの検証
        if (n <= 0) {
            throw new IllegalArgumentException("n must be a positive integer");
        }

        List<Integer> result = new ArrayList<>();

        // valueが単一の数値の場合
        if (value instanceof Number) {
            int v = ((Number) value).intValue();
            if (v <= 0) {
                throw new IllegalArgumentException("value must be positive");
            }
            for (int i = 0; i < n; i++) {
                result.add(v);
            }
            return result;
        }

        // valueがリストの場合
        if (value instanceof List) {
            List<?> list = (List<?>) value;
            if (list.size() != n) {
                throw new IllegalArgumentException("value must have length " + n);
            }
            for (Object item : list) {
                if (!(item instanceof Number)) {
                    throw new IllegalArgumentException("All elements must be numbers");
                }
                int v = ((Number) item).intValue();
                if (v <= 0) {
                    throw new IllegalArgumentException("All elements must be positive");
                }
                result.add(v);
            }
            return result;
        }

        // その他の型はエラー
        throw new IllegalArgumentException("value must be a number or a list of numbers");
    }
}
