        System.out.println(result);
    }

    public static double _calculate_similarity(String str1, String str2) {
        if (str1 == null || str2 == null || str1.isEmpty() || str2.isEmpty()) {
            return 0.0;
        }

        String norm1 = normalize(str1);
        String norm2 = normalize(str2);

        if (norm1.equals(norm2)) {
            return 1.0;
        }
        if (norm1.contains(norm2) || norm2.contains(norm1)) {
            return 0.9;
        }

        int len1 = norm1.length();
        int len2 = norm2.length();
        int maxLen = Math.max(len1, len2);
        if (maxLen == 0) {
            return 0.0;
        }

        int matches = 0;
        for (int i = 0; i < len1; i++) {
            char c = norm1.charAt(i);
            if (norm2.indexOf(c) >= 0) {
                matches++;
            }
        }

        return (double) matches / maxLen;
    }

    private static String normalize(String s) {
        // 括弧内を削除
        s = s.replaceAll("[（(].*?[）)]", "");
        s = s.replace(" ", "").replace("-", "").replace("_", "");
        return s.toLowerCase();
    }
