import java.util.*;

public class Main {
    // 実装方針: 包含関係と簡易編集距離（文字の一致率）を組み合わせて0〜1の類似度を計算する。
    public static double calculateSimilarity(Object str1, Object str2) {
        String s1 = String.valueOf(str1);
        String s2 = String.valueOf(str2);

        // 完全一致
        if (s1.equals(s2)) return 1.0;

        // 包含関係
        if (s1.contains(s2) || s2.contains(s1)) {
            double lenRatio = (double) Math.min(s1.length(), s2.length()) / Math.max(s1.length(), s2.length());
            return 0.5 + 0.5 * lenRatio;
        }

        // 簡易編集距離（文字の一致率）
        int matches = 0;
        int maxLen = Math.max(s1.length(), s2.length());
        if (maxLen == 0) return 1.0;

        // 単純な文字単位の一致数をカウント
        Map<Character, Integer> map1 = new HashMap<>();
        Map<Character, Integer> map2 = new HashMap<>();
        for (char c : s1.toCharArray()) map1.put(c, map1.getOrDefault(c, 0) + 1);
        for (char c : s2.toCharArray()) map2.put(c, map2.getOrDefault(c, 0) + 1);

        for (char c : map1.keySet()) {
            if (map2.containsKey(c)) {
                matches += Math.min(map1.get(c), map2.get(c));
            }
        }

        double similarity = (double) matches / maxLen;
        return similarity;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();

        // 簡易JSONパーサ（配列のみ対応）
        List<Object> args = parseJsonArray(input);

        Object str1 = args.get(0);
        Object str2 = args.get(1);

        double result = calculateSimilarity(str1, str2);
        System.out.println(result);
    }

    // 簡易JSON配列パーサ（文字列、数値、配列、null、真偽値に対応）
    private static List<Object> parseJsonArray(String json) {
        List<Object> list = new ArrayList<>();
        json = json.trim();
        if (json.startsWith("[")) json = json.substring(1);
        if (json.endsWith("]")) json = json.substring(0, json.length()-1);

        int i = 0;
        while (i < json.length()) {
            char c = json.charAt(i);
            if (c == ' ' || c == ',') {
                i++;
                continue;
            }
            if (c == '"') {
                // 文字列
                int end = json.indexOf('"', i+1);
                list.add(json.substring(i+1, end));
                i = end + 1;
            } else if (c == '[') {
                // 配列（再帰）
                int depth = 1;
                int j = i+1;
                while (j < json.length() && depth > 0) {
                    if (json.charAt(j) == '[') depth++;
                    else if (json.charAt(j) == ']') depth--;
                    j++;
                }
                list.add(parseJsonArray(json.substring(i, j)));
                i = j;
            } else if (c == 't' || c == 'f') {
                // 真偽値
                if (json.startsWith("true", i)) {
                    list.add(true);
                    i += 4;
                } else {
                    list.add(false);
                    i += 5;
                }
            } else if (c == 'n') {
                // null
                list.add(null);
                i += 4;
            } else {
                // 数値
                int j = i;
                while (j < json.length() && (Character.isDigit(json.charAt(j)) || json.charAt(j) == '.' || json.charAt(j) == '-')) {
                    j++;
                }
                String numStr = json.substring(i, j);
                if (numStr.contains(".")) {
                    list.add(Double.parseDouble(numStr));
                } else {
                    list.add(Long.parseLong(numStr));
                }
                i = j;
            }
        }
        return list;
    }
