using Json = std::variant<std::nullptr_t, bool, int, double, std::string, std::vector<Json>>;

// パース用の再帰下降パーサー
class JsonParser {
public:
    Json parse(const std::string& s) {
        pos = 0;
        return parseValue(s);
    }
private:
    size_t pos;
    void skipWs(const std::string& s) { while (pos < s.size() && (s[pos]==' '||s[pos]=='\t'||s[pos]=='\n'||s[pos]=='\r')) pos++; }
    Json parseValue(const std::string& s) {
        skipWs(s);
        if (pos >= s.size()) throw std::runtime_error("unexpected end");
        char c = s[pos];
        if (c == 'n') { pos += 4; return nullptr; }
        if (c == 't') { pos += 4; return true; }
        if (c == 'f') { pos += 5; return false; }
        if (c == '"') return parseString(s);
        if (c == '[') return parseArray(s);
        if (c == '-' || (c >= '0' && c <= '9')) return parseNumber(s);
        throw std::runtime_error("unexpected char");
    }
    std::string parseString(const std::string& s) {
        pos++; // skip "
        std::string res;
        while (pos < s.size() && s[pos] != '"') {
            if (s[pos] == '\\') {
                pos++;
                if (pos >= s.size()) throw std::runtime_error("bad escape");
                char e = s[pos];
                switch(e) {
                    case 'n': res += '\n'; break;
                    case 't': res += '\t'; break;
                    case 'r': res += '\r'; break;
                    case 'b': res += '\b'; break;
                    case 'f': res += '\f'; break;
                    case '/': res += '/'; break;
                    case '\\': res += '\\'; break;
                    case '"': res += '"'; break;
                    default: throw std::runtime_error("bad escape");
                }
                pos++;
            } else {
                res += s[pos++];
            }
        }
        if (pos >= s.size()) throw std::runtime_error("unterminated string");
        pos++; // skip "
        return res;
    }
    Json parseNumber(const std::string& s) {
        size_t start = pos;
        if (s[pos] == '-') pos++;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos]=='.' || s[pos]=='e' || s[pos]=='E' || s[pos]=='+' || s[pos]=='-')) pos++;
        std::string num = s.substr(start, pos-start);
        if (num.find('.') != std::string::npos || num.find('e') != std::string::npos || num.find('E') != std::string::npos) {
            return std::stod(num);
        } else {
            return (int)std::stoll(num);
        }
    }
    Json parseArray(const std::string& s) {
        pos++; // skip [
        std::vector<Json> arr;
        skipWs(s);
        if (pos < s.size() && s[pos] == ']') { pos++; return arr; }
        while (true) {
            arr.push_back(parseValue(s));
            skipWs(s);
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == ']') { pos++; break; }
            throw std::runtime_error("expected , or ]");
        }
        return arr;
    }
};

std::string jsonToString(const Json& j) {
    if (std::holds_alternative<std::nullptr_t>(j)) return "null";
    if (std::holds_alternative<bool>(j)) return std::get<bool>(j) ? "true" : "false";
    if (std::holds_alternative<int>(j)) return std::to_string(std::get<int>(j));
    if (std::holds_alternative<double>(j)) {
        std::ostringstream oss;
        oss << std::get<double>(j);
        return oss.str();
    }
    if (std::holds_alternative<std::string>(j)) {
        std::string s = std::get<std::string>(j);
        std::string res = "\"";
        for (char c : s) {
            if (c == '"') res += "\\\"";
            else if (c == '\\') res += "\\\\";
            else if (c == '\n') res += "\\n";
            else if (c == '\t') res += "\\t";
            else if (c == '\r') res += "\\r";
            else res += c;
        }
        res += "\"";
        return res;
    }
    // vector
    const auto& arr = std::get<std::vector<Json>>(j);
    std::string res = "[";
    for (size_t i = 0; i < arr.size(); i++) {
        if (i > 0) res += ",";
        res += jsonToString(arr[i]);
    }
    res += "]";
    return res;
}

// テンプレートを表現する型: 再帰的な構造
struct Node {
    bool isLeaf; // 葉ならtrue
    int value;   // 葉の場合の値(実際は使わないが、テンプレートの葉の値を保持)
    bool isTuple; // タプルかどうか(リストとタプルを区別)
    std::vector<Node> children;
};

// テンプレートをJSONからNodeに変換
Node parseTemplate(const Json& j) {
    if (std::holds_alternative<std::vector<Json>>(j)) {
        const auto& arr = std::get<std::vector<Json>>(j);
        Node n;
        n.isLeaf = false;
        n.isTuple = false; // JSON配列はリスト扱い
        for (const auto& item : arr) {
            n.children.push_back(parseTemplate(item));
        }
        return n;
    } else {
        // 葉
        Node n;
        n.isLeaf = true;
        if (std::holds_alternative<int>(j)) n.value = std::get<int>(j);
        else if (std::holds_alternative<double>(j)) n.value = (int)std::get<double>(j);
        else n.value = 0;
        n.isTuple = false;
        return n;
    }
}

// タプルを表現するための型: テンプレートのタプルはJSONでは配列として表現されるが、
// 元のPythonではタプルを区別している。しかし入力はJSON配列のみなので、タプルは扱わない。
// ただし、出力はタプルを配列として出力する仕様なので、リストとして扱う。

// unflattenの実装
Json unflatten(const std::vector<Json>& obj, const Node& templateNode, size_t& idx) {
    if (templateNode.isLeaf) {
        if (idx >= obj.size()) throw std::runtime_error("not enough elements");
        return obj[idx++];
    }
    // 非葉: 子を再帰的に処理
    std::vector<Json> res;
    for (const auto& child : templateNode.children) {
        res.push_back(unflatten(obj, child, idx));
    }
    return res;
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    JsonParser parser;
    Json input = parser.parse(line);
    // inputは [obj, template] の形式
    const auto& arr = std::get<std::vector<Json>>(input);
    if (arr.size() != 2) throw std::runtime_error("expected 2 elements");
    const Json& objJson = arr[0];
    const Json& templateJson = arr[1];

    // objをvector<Json>に変換
    std::vector<Json> obj;
    if (std::holds_alternative<std::vector<Json>>(objJson)) {
        obj = std::get<std::vector<Json>>(objJson);
    } else {
        obj.push_back(objJson);
    }

    Node templateNode = parseTemplate(templateJson);
    size_t idx = 0;
    Json result = unflatten(obj, templateNode, idx);
    // 余分な要素があっても無視(仕様通り)
    std::cout << jsonToString(result) << std::endl;
    return 0;
}
