実装方針: 入力のJSON配列からボリュームリストとスライス方向を解析し、指定された方向に応じて各ボリュームの軸を入れ替えて出力します。

```cpp
#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <cctype>

// 簡易JSONパーサ（数値・配列・文字列のみ対応）
class JsonParser {
public:
    JsonParser(const std::string& s) : str(s), pos(0) {}

    // パースして値を返す（再帰的）
    std::vector<std::vector<std::vector<int>>> parseVolumes() {
        skipWhitespace();
        expect('[');
        std::vector<std::vector<std::vector<int>>> vols;
        skipWhitespace();
        if (peek() == ']') { pos++; return vols; }
        while (true) {
            vols.push_back(parse3DArray());
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else if (peek() == ']') { pos++; break; }
            else throw std::runtime_error("parse error");
        }
        return vols;
    }

    int parseDirection() {
        skipWhitespace();
        if (peek() == '"') {
            pos++;
            std::string s;
            while (pos < str.size() && str[pos] != '"') {
                s += str[pos++];
            }
            pos++; // closing quote
            if (s == "axial") return 0;
            if (s == "sagittal") return 1;
            if (s == "coronal") return 2;
            throw std::runtime_error("unknown direction");
        }
        throw std::runtime_error("expected string");
    }

private:
    std::string str;
    size_t pos;

    void skipWhitespace() {
        while (pos < str.size() && isspace(str[pos])) pos++;
    }

    char peek() {
        if (pos < str.size()) return str[pos];
        return '\0';
    }

    void expect(char c) {
        if (peek() != c) throw std::runtime_error("expected char");
        pos++;
    }

    std::vector<std::vector<std::vector<int>>> parse3DArray() {
        skipWhitespace();
        expect('[');
        std::vector<std::vector<std::vector<int>>> arr;
        skipWhitespace();
        if (peek() == ']') { pos++; return arr; }
        while (true) {
            arr.push_back(parse2DArray());
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else if (peek() == ']') { pos++; break; }
            else throw std::runtime_error("parse error");
        }
        return arr;
    }

    std::vector<std::vector<int>> parse2DArray() {
        skipWhitespace();
        expect('[');
        std::vector<std::vector<int>> arr;
        skipWhitespace();
        if (peek() == ']') { pos++; return arr; }
        while (true) {
            arr.push_back(parse1DArray());
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else if (peek() == ']') { pos++; break; }
            else throw std::runtime_error("parse error");
        }
        return arr;
    }

    std::vector<int> parse1DArray() {
        skipWhitespace();
        expect('[');
        std::vector<int> arr;
        skipWhitespace();
        if (peek() == ']') { pos++; return arr; }
        while (true) {
            arr.push_back(parseInt());
            skipWhitespace();
            if (peek() == ',') { pos++; skipWhitespace(); }
            else if (peek() == ']') { pos++; break; }
            else throw std::runtime_error("parse error");
        }
        return arr;
    }

    int parseInt() {
        skipWhitespace();
        bool neg = false;
        if (peek() == '-') { neg = true; pos++; }
        int val = 0;
        while (pos < str.size() && isdigit(str[pos])) {
            val = val * 10 + (str[pos] - '0');
            pos++;
        }
        return neg ? -val : val;
    }
};

// ボリューム転置関数
std::vector<std::vector<std::vector<int>>> transposeVolume(
    const std::vector<std::vector<std::vector<int>>>& vol, int dir) {
    int d0 = vol.size();
    int d1 = d0 > 0 ? vol[0].size() : 0;
    int d2 = d1 > 0 ? vol[0][0].size() : 0;

    std::vector<std::vector<std::vector<int>>> result;
    if (dir == 0) { // axial: (z,y,x) -> (z,x,y) つまり軸1と軸2を入れ替え
        result.resize(d0);
        for (int z = 0; z < d0; z++) {
            result[z].resize(d2);
            for (int x = 0; x < d2; x++) {
                result[z][x].resize(d1);
                for (int y = 0; y < d1; y++) {
                    result[z][x][y] = vol[z][y][x];
                }
            }
        }
    } else if (dir == 1) { // sagittal: (z,y,x) -> (y,z,x) 軸0と軸1を入れ替え
        result.resize(d1);
        for (int y = 0; y < d1; y++) {
            result[y].resize(d0);
            for (int z = 0; z < d0; z++) {
                result[y][z].resize(d2);
                for (int x = 0; x < d2; x++) {
                    result[y][z][x] = vol[z][y][x];
                }
            }
        }
    } else { // coronal: (z,y,x) -> (x,y,z) 軸0と軸2を入れ替え
        result.resize(d2);
        for (int x = 0; x < d2; x++) {
            result[x].resize(d1);
            for (int y = 0; y < d1; y++) {
                result[x][y].resize(d0);
                for (int z = 0; z < d0; z++) {
                    result[x][y][z] = vol[z][y][x];
                }
            }
        }
    }
    return result;
}

// JSON出力（3D配列）
void print3D(const std::vector<std::vector<std::vector<int>>>& v) {
    std::cout << "[";
    for (size_t i = 0; i < v.size(); i++) {
        if (i > 0) std::cout << ",";
        std::cout << "[";
        for (size_t j = 0; j < v[i].size(); j++) {
            if (j > 0) std::cout << ",";
            std::cout << "[";
            for (size_t k = 0; k < v[i][j].size(); k++) {
                if (k > 0) std::cout << ",";
                std::cout << v[i][j][k];
            }
            std::cout << "]";
        }
        std::cout << "]";
    }
    std::cout << "]";
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    try {
        JsonParser parser(line);
        auto volumes = parser.parseVolumes();
        parser.skipWhitespace();
        if (parser.peek() == ',') parser.pos++;
        int dir = parser.parseDirection();

        std::vector<std::vector<std::vector<std::vector<int>>>> result;
        for (const auto& vol : volumes) {
            result.push_back(transposeVolume(vol, dir));
        }

        // 出力
        std::cout << "[";
        for (size_t i = 0; i < result.size(); i++) {
            if (i > 0) std::cout << ",";
            print3D(result[i]);
        }
        std::cout << "]\n";
    } catch (...) {
        std::cout << "null\n";
    }
    return 0;
}
