実装方針: 入力JSONをパースしてC++のvariant型に変換し、元のPython関数と同じ条件分岐でBiDi形式のJSONを構築して出力します。

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <set>
#include <variant>
#include <cmath>
#include <sstream>
#include <iomanip>
#include <limits>
#include <algorithm>

using Json = std::variant<std::nullptr_t, bool, int64_t, double, std::string, std::vector<Json>, std::map<std::string, Json>>;

// JSONパーサー（簡易版）
class JsonParser {
public:
    static Json parse(const std::string& s) {
        size_t pos = 0;
        return parseValue(s, pos);
    }

private:
    static void skipWhitespace(const std::string& s, size_t& pos) {
        while (pos < s.size() && (s[pos] == ' ' || s[pos] == '\t' || s[pos] == '\n' || s[pos] == '\r')) pos++;
    }

    static Json parseValue(const std::string& s, size_t& pos) {
        skipWhitespace(s, pos);
        if (pos >= s.size()) throw std::runtime_error("Unexpected end");
        char c = s[pos];
        if (c == 'n') { pos += 4; return nullptr; }
        if (c == 't') { pos += 4; return true; }
        if (c == 'f') { pos += 5; return false; }
        if (c == '"') return parseString(s, pos);
        if (c == '[') return parseArray(s, pos);
        if (c == '{') return parseObject(s, pos);
        if (c == '-' || (c >= '0' && c <= '9')) return parseNumber(s, pos);
        throw std::runtime_error("Invalid JSON");
    }

    static std::string parseString(const std::string& s, size_t& pos) {
        pos++; // skip "
        std::string result;
        while (pos < s.size() && s[pos] != '"') {
            if (s[pos] == '\\') {
                pos++;
                if (pos >= s.size()) break;
                char c = s[pos];
                switch (c) {
                    case 'n': result += '\n'; break;
                    case 't': result += '\t'; break;
                    case 'r': result += '\r'; break;
                    case '\\': result += '\\'; break;
                    case '"': result += '"'; break;
                    case '/': result += '/'; break;
                    case 'u': {
                        // 簡易的なunicode処理（実際は必要に応じて）
                        result += "\\u";
                        for (int i = 0; i < 4 && pos+1 < s.size(); i++) {
                            pos++;
                            result += s[pos];
                        }
                        break;
                    }
                    default: result += c;
                }
            } else {
                result += s[pos];
            }
            pos++;
        }
        pos++; // skip closing "
        return result;
    }

    static Json parseNumber(const std::string& s, size_t& pos) {
        size_t start = pos;
        if (s[pos] == '-') pos++;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos] == '.' || s[pos] == 'e' || s[pos] == 'E' || s[pos] == '+' || s[pos] == '-')) pos++;
        std::string numStr = s.substr(start, pos - start);
        if (numStr.find('.') != std::string::npos || numStr.find('e') != std::string::npos || numStr.find('E') != std::string::npos) {
            return std::stod(numStr);
        } else {
            try {
                return (int64_t)std::stoll(numStr);
            } catch (...) {
                return std::stod(numStr);
            }
        }
    }

    static Json parseArray(const std::string& s, size_t& pos) {
        pos++; // skip [
        std::vector<Json> arr;
        skipWhitespace(s, pos);
        if (pos < s.size() && s[pos] == ']') { pos++; return arr; }
        while (pos < s.size()) {
            arr.push_back(parseValue(s, pos));
            skipWhitespace(s, pos);
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == ']') { pos++; break; }
            throw std::runtime_error("Invalid array");
        }
        return arr;
    }

    static Json parseObject(const std::string& s, size_t& pos) {
        pos++; // skip {
        std::map<std::string, Json> obj;
        skipWhitespace(s, pos);
        if (pos < s.size() && s[pos] == '}') { pos++; return obj; }
        while (pos < s.size()) {
            skipWhitespace(s, pos);
            std::string key = parseString(s, pos);
            skipWhitespace(s, pos);
            if (pos < s.size() && s[pos] == ':') pos++;
            else throw std::runtime_error("Expected :");
            obj[key] = parseValue(s, pos);
            skipWhitespace(s, pos);
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == '}') { pos++; break; }
            throw std::runtime_error("Invalid object");
        }
        return obj;
    }
};

// JSONシリアライザー
std::string jsonToString(const Json& value) {
    if (std::holds_alternative<std::nullptr_t>(value)) return "null";
    if (std::holds_alternative<bool>(value)) return std::get<bool>(value) ? "true" : "false";
    if (std::holds_alternative<int64_t>(value)) return std::to_string(std::get<int64_t>(value));
    if (std::holds_alternative<double>(value)) {
        double d = std::get<double>(value);
        if (std::isnan(d)) return "NaN";
        if (std::isinf(d)) return d > 0 ? "Infinity" : "-Infinity";
        std::ostringstream oss;
        oss << std::setprecision(15) << d;
        return oss.str();
    }
    if (std::holds_alternative<std::string>(value)) {
        std::string s = std::get<std::string>(value);
        std::string escaped;
        for (char c : s) {
            switch (c) {
                case '"': escaped += "\\\""; break;
                case '\\': escaped += "\\\\"; break;
                case '\n': escaped += "\\n"; break;
                case '\t': escaped += "\\t"; break;
                case '\r': escaped += "\\r"; break;
                default: escaped += c;
            }
        }
        return "\"" + escaped + "\"";
    }
    if (std::holds_alternative<std::vector<Json>>(value)) {
        auto arr = std::get<std::vector<Json>>(value);
        std::string result = "[";
        for (size_t i = 0; i < arr.size(); i++) {
            if (i > 0) result += ",";
            result += jsonToString(arr[i]);
        }
        return result + "]";
    }
    if (std::holds_alternative<std::map<std::string, Json>>(value)) {
        auto obj = std::get<std::map<std::string, Json>>(value);
        std::string result = "{";
        bool first = true;
        for (const auto& [k, v] : obj) {
            if (!first) result += ",";
            first = false;
            result += jsonToString(Json(k)) + ":" + jsonToString(v);
        }
        return result + "}";
    }
    return "null";
}

// シリアライズ関数
Json serialize_value(const Json& value) {
    if (std::holds_alternative<std::nullptr_t>(value)) {
        return Json(std::map<std::string, Json>{{"type", Json(std::string("null"))}});
    }
    if (std::holds_alternative<bool>(value)) {
        return Json(std::map<std::string, Json>{{"type", Json(std::string("boolean"))}, {"value", value}});
    }
    if (std::holds_alternative<int64_t>(value)) {
        int64_t v = std::get<int64_t>(value);
        if (std::abs(v) > 9007199254740991LL) {
            return Json(std::map<std::string, Json>{{"type", Json(std::string("bigint"))}, {"value", Json(std::to_string(v))}});
        }
        return Json(std::map<std::string, Json>{{"type", Json(std::string("number"))}, {"value", Json(v)}});
    }
    if (std::holds_alternative<double>(value)) {
        double v = std::get<double>(value);
        if (std::isnan(v)) {
            return Json(std::map<std::string, Json>{{"type", Json(std::string("number"))}, {"value", Json(std::string("NaN"))}});
        }
        if (std::isinf(v)) {
            std::string infStr = v > 0 ? "Infinity" : "-Infinity";
            return Json(std::map<std::string, Json>{{"type", Json(std::string("number"))}, {"value", Json(infStr)}});
        }
        if (v == 0.0 && std::signbit(v)) {
            return Json(std::map<std::string, Json>{{"type", Json(std::string("number"))}, {"value", Json(std::string("-0"))}});
        }
        return Json(std::map<std::string, Json>{{"type", Json(std::string("number"))}, {"value", Json(v)}});
    }
    if (std::holds_alternative<std::string>(value)) {
        return Json(std::map<std::string, Json>{{"type", Json(std::string("string"))}, {"value", value}});
    }
    if (std::holds_alternative<std::vector<Json>>(value)) {
        auto arr = std::get<std::vector<Json>>(value);
        std::vector<Json> serialized;
        for (const auto& item : arr) {
            serialized.push_back(serialize_value(item));
        }
        return Json(std::map<std::string, Json>{{"type", Json(std::string("array"))}, {"value", Json(serialized)}});
    }
    if (std::holds_alternative<std::map<std::string, Json>>(value)) {
        auto obj = std::get<std::map<std::string, Json>>(value);
        if (obj.find("sharedId") != obj.end()) {
            return Json(std::map<std::string, Json>{{"type", Json(std::string("sharedReference"))}, {"sharedId", obj["sharedId"]}});
        }
        std::vector<Json> pairs;
        for (const auto& [k, v] : obj) {
            std::vector<Json> pair;
            // キーが文字列以外は考慮しない（JSONオブジェクトのキーは常に文字列）
            pair.push_back(Json(k));
            pair.push_back(serialize_value(v));
            pairs.push_back(Json(pair));
        }
        return Json(std::map<std::string, Json>{{"type", Json(std::string("object"))}, {"value", Json(pairs)}});
    }
    // その他（setやカスタムオブジェクトはJSON入力では表現されないため、文字列化）
    return Json(std::map<std::string, Json>{{"type", Json(std::string("string"))}, {"value", Json(jsonToString(value))}});
}

int main() {
    std::string input;
    std::getline(std::cin, input);
    try {
        Json parsed = JsonParser::parse(input);
        // 入力は配列形式で、最初の要素が引数
        if (std::holds_alternative<std::vector<Json>>(parsed)) {
            auto args = std::get<std::vector<Json>>(parsed);
            if (!args.empty()) {
                Json result = serialize_value(args[0]);
                std::cout << jsonToString(result) << std::endl;
                return 0;
            }
        }
        std::cout << "null" << std::endl;
    } catch (...) {
        std::cout << "null" << std::endl;
    }
    return 0;
}
