    std::optional<int> stopped_score;
    std::optional<int> never_score;
    std::optional<int> compliance_score;
    std::map<std::string, std::string> additional_properties; // 追加プロパティ（文字列と仮定）

    // to_dictに相当する関数
    std::string to_dict() const {
        std::ostringstream oss;
        oss << "{";
        bool first = true;

        auto add_field = [&](const std::string& key, const std::optional<int>& val) {
            if (val.has_value()) {
                if (!first) oss << ",";
                oss << "\"" << key << "\":" << *val;
                first = false;
            }
        };

        add_field("currentScore", current_score);
        add_field("stoppedScore", stopped_score);
        add_field("neverScore", never_score);
        add_field("complianceScore", compliance_score);

        // 追加プロパティ
        for (const auto& [key, value] : additional_properties) {
            if (!value.empty()) { // Noneに相当する空文字列はスキップ
                if (!first) oss << ",";
                oss << "\"" << json_escape(key) << "\":\"" << json_escape(value) << "\"";
                first = false;
            }
        }

        oss << "}";
        return oss.str();
    }
};

