```cpp
#include <iostream>
#include <string>
#include <vector>
#include <variant>
#include <map>
#include <sstream>
#include <cctype>

// JSONパーサー（簡易版）
class JsonValue {
public:
    using Array = std::vector<JsonValue>;
    using Object = std::map<std::string, JsonValue>;
    std::variant<std::nullptr_t, bool, int, double, std::string, Array, Object> data;

    bool isArray() const { return std::holds_alternative<Array>(data); }
    bool isString() const { return std::holds_alternative<std::string>(data); }
    bool isNull() const { return std::holds_alternative<std::nullptr_t>(data); }
    const Array& getArray() const { return std::get<Array>(data); }
    const std::string& getString() const { return std::get<std::string>(data); }
};

// 簡易JSONパーサー（再帰下降）
class JsonParser {
    std::string s;
    size_t pos = 0;
public:
    JsonParser(const std::string& str) : s(str) {}
    JsonValue parse() {
        skipWs();
        return parseValue();
    }
private:
    void skipWs() { while (pos < s.size() && isspace(s[pos])) pos++; }
    JsonValue parseValue() {
        if (pos >= s.size()) return JsonValue{nullptr};
        char c = s[pos];
        if (c == '[') return parseArray();
        if (c == '{') return parseObject();
        if (c == '"') return parseString();
        if (c == 't' || c == 'f') return parseBool();
        if (c == 'n') { pos += 4; return JsonValue{nullptr}; }
        return parseNumber();
    }
    JsonValue parseArray() {
        pos++; // '['
        JsonValue::Array arr;
        skipWs();
        if (pos < s.size() && s[pos] == ']') { pos++; return JsonValue{arr}; }
        while (true) {
            arr.push_back(parseValue());
            skipWs();
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == ']') { pos++; break; }
            break;
        }
        return JsonValue{arr};
    }
    JsonValue parseObject() {
        pos++; // '{'
        JsonValue::Object obj;
        skipWs();
        if (pos < s.size() && s[pos] == '}') { pos++; return JsonValue{obj}; }
        while (true) {
            skipWs();
            if (pos >= s.size() || s[pos] != '"') break;
            std::string key = parseString().getString();
            skipWs();
            if (pos < s.size() && s[pos] == ':') pos++;
            JsonValue val = parseValue();
            obj[key] = val;
            skipWs();
            if (pos < s.size() && s[pos] == ',') { pos++; continue; }
            if (pos < s.size() && s[pos] == '}') { pos++; break; }
            break;
        }
        return JsonValue{obj};
    }
    JsonValue parseString() {
        pos++; // '"'
        std::string res;
        while (pos < s.size() && s[pos] != '"') {
            if (s[pos] == '\\' && pos+1 < s.size()) {
                pos++;
                if (s[pos] == 'n') res += '\n';
                else if (s[pos] == 't') res += '\t';
                else if (s[pos] == 'r') res += '\r';
                else if (s[pos] == '\\') res += '\\';
                else if (s[pos] == '"') res += '"';
                else res += s[pos];
            } else {
                res += s[pos];
            }
            pos++;
        }
        pos++; // '"'
        return JsonValue{res};
    }
    JsonValue parseBool() {
        if (s.compare(pos, 4, "true") == 0) { pos += 4; return JsonValue{true}; }
        if (s.compare(pos, 5, "false") == 0) { pos += 5; return JsonValue{false}; }
        return JsonValue{nullptr};
    }
    JsonValue parseNumber() {
        size_t start = pos;
        while (pos < s.size() && (isdigit(s[pos]) || s[pos]=='-' || s[pos]=='.' || s[pos]=='e' || s[pos]=='E' || s[pos]=='+')) pos++;
        std::string num = s.substr(start, pos-start);
        if (num.find('.') != std::string::npos || num.find('e') != std::string::npos || num.find('E') != std::string::npos) {
            return JsonValue{std::stod(num)};
        }
        return JsonValue{std::stoi(num)};
    }
};

// タグ判定用ヘルパー
bool isSkipTag(const std::string& tag) {
    return tag == "skip" || tag == "deepseek_v4_pending";
}

bool isCumulativeTag(const std::string& tag) {
    return tag == "cumulative" || tag == "deepseek_v4";
}

// 再帰的検査
void checkEntry(const JsonValue& entry, bool& has_skip, bool& has_cumulative) {
    if (!entry.isArray() || entry.getArray().empty()) return;
    const auto& arr = entry.getArray();
    if (!arr[0].isString()) return;
    std::string tag = arr[0].getString();

    if (isSkipTag(tag)) {
        has_skip = true;
    } else if (tag == "deepseek_v4_delta_v1") {
        // アンカー種別がNoneかどうか（簡易判定: 要素数が1以下ならNone）
        if (arr.size() <= 1) {
            has_skip = true;
        } else {
            has_cumulative = true;
        }
    } else if (isCumulativeTag(tag)) {
        has_cumulative = true;
    } else if (tag == "zaya_cca") {
        if (arr.size() > 2 && !arr[2].isNull()) {
            has_cumulative = true;
        } else {
            has_skip = true;
        }
    } else if (tag == "cache_list" && arr.size() > 1) {
        const auto& sublist = arr[1];
        if (sublist.isArray()) {
            for (const auto& sub : sublist.getArray()) {
                if (sub.isArray() && !sub.getArray().empty()) {
                    const auto& subarr = sub.getArray();
                    if (subarr[0].isString()) {
                        std::string subtag = subarr[0].getString();
                        if (isSkipTag(subtag)) has_skip = true;
                        else if (isCumulativeTag(subtag)) has_cumulative = true;
                    }
                }
            }
        }
    }
}

bool block_needs_cumulative_update(const JsonValue& cache_data) {
    if (!cache_data.isArray() || cache_data.getArray().empty()) return false;
    bool has_skip = false;
    bool has_cumulative = false;
    for (const auto& entry : cache_data.getArray()) {
        checkEntry(entry, has_skip, has_cumulative);
    }
    return has_skip && !has_cumulative;
}

int main() {
    std::string line;
    std::getline(std::cin, line);
    JsonParser parser(line);
    JsonValue arg = parser.parse();
    bool result = block_needs_cumulative_update(arg);
    std::cout << (result ? "true" : "false") << std::endl;
    return 0;
}
