実装方針: ブロックのデータ構造を再帰的に探索し、トップレベルとサブスライスに"skip"エントリが存在し、"cumulative"エントリが存在しない場合にtrueを返す。

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <variant>
#include <sstream>

using Json = std::variant<std::nullptr_t, bool, int, double, std::string, std::vector<Json>, std::map<std::string, Json>>;

// JSONパーサー（簡易版）
class JsonParser {
public:
    static Json parse(const std::string& str) {
        size_t pos = 0;
        return parseValue(str, pos);
    }

private:
    static void skipWhitespace(const std::string& str, size_t& pos) {
        while (pos < str.size() && (str[pos] == ' ' || str[pos] == '\t' || str[pos] == '\n' || str[pos] == '\r')) pos++;
    }

    static Json parseValue(const std::string& str, size_t& pos) {
        skipWhitespace(str, pos);
        if (pos >= str.size()) return nullptr;
        char c = str[pos];
        if (c == 'n') { pos += 4; return nullptr; }
        if (c == 't') { pos += 4; return true; }
        if (c == 'f') { pos += 5; return false; }
        if (c == '"') return parseString(str, pos);
        if (c == '[') return parseArray(str, pos);
        if (c == '{') return parseObject(str, pos);
        if (c == '-' || (c >= '0' && c <= '9')) return parseNumber(str, pos);
        throw std::runtime_error("Invalid JSON");
    }

    static std::string parseString(const std::string& str, size_t& pos) {
        pos++; // skip '"'
        std::string result;
        while (pos < str.size() && str[pos] != '"') {
            if (str[pos] == '\\') {
                pos++;
                if (pos < str.size()) {
                    switch (str[pos]) {
                        case 'n': result += '\n'; break;
                        case 't': result += '\t'; break;
                        case 'r': result += '\r'; break;
                        case 'b': result += '\b'; break;
                        case 'f': result += '\f'; break;
                        case '\\': result += '\\'; break;
                        case '"': result += '"'; break;
                        default: result += str[pos];
                    }
                }
            } else {
                result += str[pos];
            }
            pos++;
        }
        pos++; // skip closing '"'
        return result;
    }

    static Json parseNumber(const std::string& str, size_t& pos) {
        size_t start = pos;
        if (str[pos] == '-') pos++;
        while (pos < str.size() && (isdigit(str[pos]) || str[pos] == '.' || str[pos] == 'e' || str[pos] == 'E' || str[pos] == '+' || str[pos] == '-')) pos++;
        std::string numStr = str.substr(start, pos - start);
        if (numStr.find('.') != std::string::npos || numStr.find('e') != std::string::npos || numStr.find('E') != std::string::npos) {
            return std::stod(numStr);
        }
        return std::stoi(numStr);
    }

    static Json parseArray(const std::string& str, size_t& pos) {
        pos++; // skip '['
        std::vector<Json> arr;
        skipWhitespace(str, pos);
        if (pos < str.size() && str[pos] == ']') { pos++; return arr; }
        while (true) {
            arr.push_back(parseValue(str, pos));
            skipWhitespace(str, pos);
            if (pos < str.size() && str[pos] == ',') { pos++; continue; }
            if (pos < str.size() && str[pos] == ']') { pos++; break; }
            throw std::runtime_error("Invalid array");
        }
        return arr;
    }

    static Json parseObject(const std::string& str, size_t& pos) {
        pos++; // skip '{'
        std::map<std::string, Json> obj;
        skipWhitespace(str, pos);
        if (pos < str.size() && str[pos] == '}') { pos++; return obj; }
        while (true) {
            skipWhitespace(str, pos);
            std::string key = parseString(str, pos);
            skipWhitespace(str, pos);
            if (pos < str.size() && str[pos] == ':') pos++;
            obj[key] = parseValue(str, pos);
            skipWhitespace(str, pos);
            if (pos < str.size() && str[pos] == ',') { pos++; continue; }
            if (pos < str.size() && str[pos] == '}') { pos++; break; }
            throw std::runtime_error("Invalid object");
        }
        return obj;
    }
};

// JSONシリアライザー
std::string jsonToString(const Json& value) {
    if (std::holds_alternative<std::nullptr_t>(value)) return "null";
    if (std::holds_alternative<bool>(value)) return std::get<bool>(value) ? "true" : "false";
    if (std::holds_alternative<int>(value)) return std::to_string(std::get<int>(value));
    if (std::holds_alternative<double>(value)) {
        std::ostringstream ss;
        ss << std::get<double>(value);
        return ss.str();
    }
    if (std::holds_alternative<std::string>(value)) {
        std::string s = std::get<std::string>(value);
        std::string escaped;
        for (char c : s) {
            if (c == '"') escaped += "\\\"";
            else if (c == '\\') escaped += "\\\\";
            else if (c == '\n') escaped += "\\n";
            else if (c == '\t') escaped += "\\t";
            else escaped += c;
        }
        return "\"" + escaped + "\"";
    }
    if (std::holds_alternative<std::vector<Json>>(value)) {
        const auto& arr = std::get<std::vector<Json>>(value);
        std::string result = "[";
        for (size_t i = 0; i < arr.size(); i++) {
            if (i > 0) result += ",";
            result += jsonToString(arr[i]);
        }
        result += "]";
        return result;
    }
    if (std::holds_alternative<std::map<std::string, Json>>(value)) {
        const auto& obj = std::get<std::map<std::string, Json>>(value);
        std::string result = "{";
        bool first = true;
        for (const auto& [k, v] : obj) {
            if (!first) result += ",";
            result += "\"" + k + "\":" + jsonToString(v);
            first = false;
        }
        result += "}";
        return result;
    }
    return "null";
}

