bool hasSkipWithoutCumulative(const Json& data) {
    if (std::holds_alternative<std::map<std::string, Json>>(data)) {
        const auto& obj = std::get<std::map<std::string, Json>>(data);
        bool hasSkip = obj.find("skip") != obj.end();
        bool hasCumulative = obj.find("cumulative") != obj.end();
        if (hasSkip && !hasCumulative) return true;
        // サブスライスを再帰的にチェック
        for (const auto& [key, value] : obj) {
            if (key == "CacheList" || key == "sub_slices" || key == "entries") {
                if (hasSkipWithoutCumulative(value)) return true;
            }
        }
    } else if (std::holds_alternative<std::vector<Json>>(data)) {
        const auto& arr = std::get<std::vector<Json>>(data);
        for (const auto& item : arr) {
            if (hasSkipWithoutCumulative(item)) return true;
        }
    }
    return false;
}

