#include <iostream>
#include <string>
#include <vector>
#include <sstream>
#include <cctype>

// 簡易JSONパーサ（必要な範囲のみ）
std::string trim(const std::string& s) {
    size_t start = s.find_first_not_of(" \t\n\r");
    if (start == std::string::npos) return "";
    size_t end = s.find_last_not_of(" \t\n\r");
    return s.substr(start, end - start + 1);
}

// 配列の要素を文字列として取得（簡易版）
std::vector<std::string> parseArray(const std::string& json) {
    std::vector<std::string> elements;
    std::string content = trim(json);
    if (content.size() < 2 || content[0] != '[' || content[content.size()-1] != ']') {
        return elements;
    }
    content = content.substr(1, content.size() - 2);
    std::string current;
    int depth = 0;
    bool inString = false;
    for (char c : content) {
        if (c == '"' && (current.empty() || current.back() != '\\')) {
            inString = !inString;
        }
        if (!inString) {
            if (c == '[' || c == '{') depth++;
            else if (c == ']' || c == '}') depth--;
            else if (c == ',' && depth == 0) {
                elements.push_back(trim(current));
                current.clear();
                continue;
            }
        }
        current += c;
    }
    if (!trim(current).empty()) elements.push_back(trim(current));
    return elements;
}

int main() {
