    } else if (!firstArg.empty() && (firstArg[0] == '"' || firstArg == "null" || firstArg == "true" || firstArg == "false")) {
        errorMsg = "'str' object has no attribute 'minioClient'";
    } else {
        errorMsg = "'int' object has no attribute 'minioClient'";
    }

    // JSONエスケープ（簡易）
