```csharp
using System;
using System.Collections.Generic;
using System.Text;

class Program
{
    static List<double> SampleList(List<object> values, int maxSamples)
    {
        int n = values.Count;
        if (n == 0) return new List<double>();
        if (n <= maxSamples)
        {
            var result = new List<double>();
            foreach (var v in values)
                result.Add(Convert.ToDouble(v));
            return result;
        }
        var indices = new List<int>();
        for (int i = 0; i < maxSamples; i++)
            indices.Add((int)(i * n / (double)maxSamples));
        var sampled = new List<double>();
        foreach (int idx in indices)
            sampled.Add(Convert.ToDouble(values[idx]));
        return sampled;
    }

    static object ParseJson(string json, ref int pos)
    {
        // 簡易JSONパーサー（数値、配列、文字列、bool、null対応）
        while (pos < json.Length && char.IsWhiteSpace(json[pos])) pos++;
        if (pos >= json.Length) return null;

        char c = json[pos];
        if (c == '[')
        {
            pos++;
            var list = new List<object>();
            while (true)
            {
                while (pos < json.Length && char.IsWhiteSpace(json[pos])) pos++;
                if (pos < json.Length && json[pos] == ']') { pos++; break; }
                list.Add(ParseJson(json, ref pos));
                while (pos < json.Length && char.IsWhiteSpace(json[pos])) pos++;
                if (pos < json.Length && json[pos] == ',') pos++;
                else if (pos < json.Length && json[pos] == ']') { pos++; break; }
            }
            return list;
        }
        else if (c == '"')
        {
            pos++;
            var sb = new StringBuilder();
            while (pos < json.Length && json[pos] != '"')
            {
                if (json[pos] == '\\' && pos + 1 < json.Length)
                {
                    pos++;
                    if (json[pos] == 'n') sb.Append('\n');
                    else if (json[pos] == 't') sb.Append('\t');
                    else if (json[pos] == '\\') sb.Append('\\');
                    else if (json[pos] == '"') sb.Append('"');
                    else sb.Append(json[pos]);
                }
                else sb.Append(json[pos]);
                pos++;
            }
            if (pos < json.Length) pos++;
            return sb.ToString();
        }
        else if (c == 't' && json.Substring(pos, 4) == "true") { pos += 4; return true; }
        else if (c == 'f' && json.Substring(pos, 5) == "false") { pos += 5; return false; }
        else if (c == 'n' && json.Substring(pos, 4) == "null") { pos += 4; return null; }
        else
        {
            // 数値
            int start = pos;
            while (pos < json.Length && (char.IsDigit(json[pos]) || json[pos] == '-' || json[pos] == '.' || json[pos] == 'e' || json[pos] == 'E' || json[pos] == '+' || json[pos] == 'x')) pos++;
            string numStr = json.Substring(start, pos - start);
            if (numStr.Contains(".") || numStr.Contains("e") || numStr.Contains("E"))
                return double.Parse(numStr, System.Globalization.CultureInfo.InvariantCulture);
            else
                return long.Parse(numStr);
        }
    }

    static string ToJson(object obj)
    {
        if (obj == null) return "null";
        if (obj is bool b) return b ? "true" : "false";
        if (obj is double d) return d.ToString("R", System.Globalization.CultureInfo.InvariantCulture);
        if (obj is long l) return l.ToString();
        if (obj is int i) return i.ToString();
        if (obj is string s) return "\"" + s.Replace("\\", "\\\\").Replace("\"", "\\\"") + "\"";
        if (obj is List<object> list)
        {
            var sb = new StringBuilder("[");
            for (int j = 0; j < list.Count; j++)
            {
                if (j > 0) sb.Append(",");
                sb.Append(ToJson(list[j]));
            }
            sb.Append("]");
            return sb.ToString();
        }
        return "null";
    }

    static void Main()
    {
        string input = Console.ReadLine();
        int pos = 0;
        var args = (List<object>)ParseJson(input, ref pos);
        var values = (List<object>)args[0];
        int maxSamples = Convert.ToInt32(args[1]);
        var result = SampleList(values, maxSamples);
        // 結果をList<object>に変換
        var resultObj = new List<object>();
        foreach (var v in result) resultObj.Add(v);
        Console.WriteLine(ToJson(resultObj));
    }
}
