```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

class Program
{
    static List<float> EvenlySample(List<object> values, int maxSamples)
    {
        var floats = values.Select(v => Convert.ToSingle(v)).ToList();
        if (floats.Count <= maxSamples)
            return floats;

        var result = new List<float>();
        for (int i = 0; i < maxSamples; i++)
        {
            double index = (double)i * (floats.Count - 1) / (maxSamples - 1);
            int idx = (int)Math.Round(index);
