```csharp
using System;
using System.Collections.Generic;
using System.Text.Json;

class Program
{
    static (int[], int[]) ComputeSendRouting(int[] outputIndices, int chunkSize)
    {
        // 妥当性チェック
        if (chunkSize <= 0)
            throw new ArgumentException("chunk_size must be positive");

        foreach (int idx in outputIndices)
        {
            if (idx < 0)
                throw new ArgumentException("output_indices must be non-negative");
        }

        int sizeM = outputIndices.Length;
        int[] sendDestChips = new int[sizeM];
        int[] sendLocalRows = new int[sizeM];

        for (int i = 0; i < sizeM; i++)
        {
            sendDestChips[i] = outputIndices[i] / chunkSize;
            sendLocalRows[i] = outputIndices[i] % chunkSize;
        }

        return (sendDestChips, sendLocalRows);
    }

    static void Main()
    {
        string input = Console.ReadLine();
        var args = JsonSerializer.Deserialize<JsonElement>(input);

        int[] outputIndices = args[0].EnumerateArray().Select(x => x.GetInt32()).ToArray();
        int chunkSize = args[1].GetInt32();

        try
        {
            var result = ComputeSendRouting(outputIndices, chunkSize);
            var output = new int[][] { result.Item1, result.Item2 };
            Console.WriteLine(JsonSerializer.Serialize(output));
        }
        catch (ArgumentException ex)
        {
            Console.WriteLine(JsonSerializer.Serialize(new { error = ex.Message }));
        }
    }
}
