using System;
using System.Collections.Generic;
using System.Text.Json;

class Program
{
    static string _extract_content(JsonElement content, Dictionary<string, string> tool_use_map = null)
    {
        if (content.ValueKind == JsonValueKind.String)
        {
            return content.GetString().Trim();
        }
        if (content.ValueKind == JsonValueKind.Array)
        {
            var parts = new List<string>();
            foreach (var item in content.EnumerateArray())
            {
                if (item.ValueKind == JsonValueKind.String)
                {
                    parts.Add(item.GetString());
                }
                else if (item.ValueKind == JsonValueKind.Object)
                {
                    string blockType = "";
                    if (item.TryGetProperty("type", out JsonElement typeElem))
                        blockType = typeElem.GetString();

                    if (blockType == "text")
                    {
                        if (item.TryGetProperty("text", out JsonElement textElem))
                            parts.Add(textElem.GetString() ?? "");
                    }
                    else if (blockType == "tool_use")
                    {
                        parts.Add(_format_tool_use(item));
                    }
                    else if (blockType == "tool_result")
                    {
                        string tid = "";
                        if (item.TryGetProperty("tool_use_id", out JsonElement tidElem))
                            tid = tidElem.GetString() ?? "";

                        string tname = "Unknown";
                        if (tool_use_map != null && tool_use_map.ContainsKey(tid))
                            tname = tool_use_map[tid];

                        string resultContent = "";
                        if (item.TryGetProperty("content", out JsonElement contentElem))
                            resultContent = contentElem.ToString();

                        string formatted = _format_tool_result(resultContent, tname);
                        if (!string.IsNullOrEmpty(formatted))
                            parts.Add(formatted);
                    }
                }
            }
            var filtered = parts.FindAll(p => !string.IsNullOrEmpty(p));
            return string.Join("\n", filtered).Trim();
        }
        if (content.ValueKind == JsonValueKind.Object)
        {
            if (content.TryGetProperty("text", out JsonElement textElem))
                return textElem.GetString().Trim();
            return "";
        }
        return "";
    }

    static string _format_tool_use(JsonElement item)
    {
        // 簡易実装: tool_use_idとnameを表示
        string id = "";
        string name = "";
        if (item.TryGetProperty("id", out JsonElement idElem))
            id = idElem.GetString() ?? "";
        if (item.TryGetProperty("name", out JsonElement nameElem))
            name = nameElem.GetString() ?? "";
        return $"[tool_use: {name}({id})]";
    }

    static string _format_tool_result(string content, string toolName)
    {
        // 簡易実装: ツール名と内容を表示
        return $"[tool_result: {toolName}] {content}";
    }

    static void Main()
    {
        string input = Console.ReadLine();
        using JsonDocument doc = JsonDocument.Parse(input);
        JsonElement root = doc.RootElement;

        // 引数は配列形式: [content, tool_use_map?]
        JsonElement content = root[0];
        Dictionary<string, string> map = null;
        if (root.GetArrayLength() > 1 && root[1].ValueKind == JsonValueKind.Object)
        {
            map = new Dictionary<string, string>();
            foreach (var prop in root[1].EnumerateObject())
            {
                map[prop.Name] = prop.Value.GetString();
            }
        }

        string result = _extract_content(content, map);
        Console.WriteLine(JsonSerializer.Serialize(result));
    }
}
