func elementOrder(element, modulus, phiM int, phiMDecomposition map[int]int) interface{} {
	if element == 1 {
		return 1
	}
	if modPow(element, phiM, modulus) != 1 {
		return nil
	}
	order := phiM
	for factor, power := range phiMDecomposition {
		for p := 1; p <= power; p++ {
			nextOrder := order / factor
			if modPow(element, nextOrder, modulus) == 1 {
				order = nextOrder
			} else {
				break
			}
		}
	}
	return order
}

func modPow(base, exp, mod int) int {
	result := 1
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
}

func main() {
