```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
)

func orderOfElement(element, modulus, phiM int64, phiMDecomposition [][]int64) interface{} {
	// 要素が法と互いに素でない場合は位数が定義されない
	if gcd(element, modulus) != 1 {
		return nil
	}

	// 位数はphiMの約数であるため、phiMの各素因数について
	// 位数を割り切るかどうかを確認する
	order := phiM
	for _, factor := range phiMDecomposition {
		p := factor[0]
		// pがorderを割り切る間、orderをpで割ってみる
		for order%p == 0 {
			temp := order / p
			if modPow(element, temp, modulus) == 1 {
				order = temp
			} else {
				break
			}
		}
	}
	return order
}

func gcd(a, b int64) int64 {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func modPow(base, exp, mod int64) int64 {
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
}

func main() {
	var input []json.RawMessage
	decoder := json.NewDecoder(os.Stdin)
	if err := decoder.Decode(&input); err != nil {
		return
	}

	var element, modulus, phiM int64
	var phiMDecomposition [][]int64

	json.Unmarshal(input[0], &element)
	json.Unmarshal(input[1], &modulus)
	json.Unmarshal(input[2], &phiM)
	json.Unmarshal(input[3], &phiMDecomposition)

	result := orderOfElement(element, modulus, phiM, phiMDecomposition)

	output, _ := json.Marshal(result)
	fmt.Println(string(output))
}
```

