func degminsec2deg(stringArg string, back float64) string {
	stringVal := stringArg
	if strings.Contains(stringVal, ":") {
		val := 0.0
		numlist := strings.Split(stringVal, ":")
		for idx, ele := range numlist {
			f, err := strconv.ParseFloat(ele, 64)
			if err != nil {
				val = 999.0
				break
			}
			pow := 1.0
			for i := 0; i < idx; i++ {
				pow *= 60.0
			}
			val += f / pow
		}
		if val < -180 || val > 360 {
			return "999.0"
		}
		if back == 1.0 {
			// decdeg2dms
			isPositive := val >= 0
			dd := val
			if dd < 0 {
				dd = -dd
			}
			totalSeconds := dd * 3600
			minutes := int(totalSeconds) / 60
			seconds := totalSeconds - float64(minutes*60)
			degrees := minutes / 60
			minutes = minutes % 60
			if !isPositive {
				degrees = -degrees
			}
			return fmt.Sprintf("%d:%d:%f", degrees, minutes, seconds)
		}
		return strconv.FormatFloat(val, 'f', -1, 64)
	} else {
		if strings.Contains(stringVal, ",") {
			stringVal = strings.Replace(stringVal, ",", ".", -1)
		}
		val, err := strconv.ParseFloat(stringVal, 64)
		if err != nil {
			val = 999.0
		}
		if val < -180 || val > 360 {
			return "999.0"
		}
		if back == 1.0 {
