```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func deg(input string, back float64) string {
	// 入力が「度:分:秒」形式か「度.小数」形式かを判定
	if strings.Contains(input, ":") {
		// 度:分:秒形式を度.小数に変換
		parts := strings.Split(input, ":")
		if len(parts) != 3 {
			return ""
		}
		degVal, err1 := strconv.ParseFloat(parts[0], 64)
		minVal, err2 := strconv.ParseFloat(parts[1], 64)
		secVal, err3 := strconv.ParseFloat(parts[2], 64)
		if err1 != nil || err2 != nil || err3 != nil {
			return ""
		}
		decimal := degVal + minVal/60.0 + secVal/3600.0
		if back == 1.0 {
			// 度.小数を返す
			return strconv.FormatFloat(decimal, 'f', -1, 64)
		} else {
			// 度:分:秒を返す（入力が既にその形式なのでそのまま）
			return input
		}
	} else {
		// 度.小数形式
		decimalVal, err := strconv.ParseFloat(input, 64)
		if err != nil {
			return ""
		}
		if back == 1.0 {
			// 度.小数を返す
			return strconv.FormatFloat(decimalVal, 'f', -1, 64)
		} else {
			// 度:分:秒に変換
			degPart := int(decimalVal)
			minFloat := (decimalVal - float64(degPart)) * 60
			minPart := int(minFloat)
			secFloat := (minFloat - float64(minPart)) * 60
			secPart := int(secFloat)
			return fmt.Sprintf("%d:%d:%d", degPart, minPart, secPart)
		}
	}
}

func main() {
	var params []interface{}
	if err := json.NewDecoder(os.Stdin).Decode(&params); err != nil {
		return
	}
	if len(params) != 2 {
		return
	}
	inputStr, ok1 := params[0].(string)
	backFloat, ok2 := params[1].(float64)
	if !ok1 || !ok2 {
		return
	}
	result := deg(inputStr, backFloat)
	output, _ := json.Marshal(result)
	fmt.Println(string(output))
}
