```go
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func intToBits(i int, width *int) []int {
	var binStr string
	if width != nil {
		binStr = fmt.Sprintf("%0*b", *width, i)
	} else {
		binStr = strconv.FormatInt(int64(i), 2)
	}
	// LSB firstにするため反転
	reversed := reverseString(binStr)
	bits := make([]int, len(reversed))
	for idx, ch := range reversed {
		if ch == '1' {
			bits[idx] = 1
		} else {
			bits[idx] = 0
		}
	}
	return bits
}

func reverseString(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

func main() {
	var input []json.RawMessage
	decoder := json.NewDecoder(os.Stdin)
	if err := decoder.Decode(&input); err != nil {
		panic(err)
	}

	var i int
	if err := json.Unmarshal(input[0], &i); err != nil {
		panic(err)
	}

	var width *int
	if len(input) > 1 && string(input[1]) != "null" {
		var w int
		if err := json.Unmarshal(input[1], &w); err != nil {
			panic(err)
		}
		width = &w
	}

	result := intToBits(i, width)
	output, err := json.Marshal(result)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(output))
}
