const DEFAULT_SAMTOOLS_MAX_MEM_MB_PER_THREAD = 768

func getSamtoolsResParam(subcmd string, nth int, memGb *float64) string {
    resParam := ""
    if subcmd == "index" {
        resParam += fmt.Sprintf("-@ %d ", nth)
    } else {
        resParam += fmt.Sprintf("-@ %d ", nth-1)
    }
    if subcmd == "sort" {
        if nth > 0 && memGb != nil {
            memMbPerThread := int(math.Floor(*memGb * 1024.0 / float64(nth)))
            if memMbPerThread > DEFAULT_SAMTOOLS_MAX_MEM_MB_PER_THREAD {
                memMbPerThread = DEFAULT_SAMTOOLS_MAX_MEM_MB_PER_THREAD
            }
            if memMbPerThread < 1 {
                memMbPerThread = 1
            }
            resParam += fmt.Sprintf("-m %dM ", memMbPerThread)
        }
    }
    return resParam
}

func main() {
    var args []interface{}
    if err := json.NewDecoder(os.Stdin).Decode(&args); err != nil {
        panic(err)
    }
    subcmd := args[0].(string)
    nth := int(args[1].(float64))
    var memGb *float64
    if args[2] != nil {
        v := args[2].(float64)
        memGb = &v
