```rust
use std::collections::HashMap;
use std::env;
use std::fs::File;
use std::io::{BufRead, BufReader};

fn get_trna_pos(path: &str) -> Option<HashMap<String, Vec<String>>> {
    let file = File::open(path).ok()?;
    let reader = BufReader::new(file);
    let mut trnas: HashMap<String, Vec<String>> = HashMap::new();

    for line in reader.lines() {
        let line = line.ok()?;
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 7 {
            continue;
        }
        if parts[2] == "tRNA" {
            let start = parts[3].to_string();
            let strand = parts[6].to_string();
            let info = parts.last().unwrap().trim();
            if let Some(pos) = info.find("gene_id=") {
                let gene_id = &info[pos + 8..];
                trnas.insert(gene_id.to_string(), vec![start, strand]);
            }
        }
    }

    if trnas.is_empty() {
        None
    } else {
        Some(trnas)
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 2 {
        eprintln!("Usage: program <path>");
        std::process::exit(1);
    }
    let result = get_trna_pos(&args[1]);
    let json = match result {
        Some(map) => {
            let mut items = Vec::new();
            for (k, v) in map {
                let v_json = format!("[\"{}\", \"{}\"]", v[0], v[1]);
                items.push(format!("\"{}\": {}", k, v_json));
            }
            format!("{{{}}}", items.join(","))
        }
        None => "null".to_string(),
    };
    println!("{}", json);
}
