```rust
use std::fs::File;
use std::io::{BufRead, BufReader};
use std::collections::HashMap;

fn main() {
    let mut input = String::new();
    std::io::stdin().read_line(&mut input).unwrap();
    let args: Vec<String> = serde_json::from_str(&input).unwrap();
    let path = &args[0];
    let result = process_file(path);
    println!("{}", serde_json::to_string(&result).unwrap());
}

fn process_file(path: &str) -> Option<HashMap<String, Vec<usize>>> {
    let file = File::open(path).ok()?;
    let reader = BufReader::new(file);
    let mut positions: HashMap<String, Vec<usize>> = HashMap::new();
    let mut current_gene: Option<String> = None;
    let mut current_pos: usize = 0;
    let mut line_num = 0;

    for line in reader.lines() {
        let line = line.ok()?;
        line_num += 1;
        if line.starts_with('>') {
            // ヘッダー行: 遺伝子名を取得
            let header = &line[1..];
            let name = header.split_whitespace().next().unwrap_or("").to_string();
            if name.contains("tRNA") {
                current_gene = Some(name);
                current_pos = line_num; // ヘッダー行の位置を記録
            } else {
                current_gene = None;
            }
        } else if let Some(gene) = &current_gene {
            // 配列行: 位置を記録（ヘッダー行の次の行から）
            if line_num == current_pos + 1 {
                positions.entry(gene.clone()).or_insert_with(Vec::new).push(line_num);
            }
        }
    }

    if positions.is_empty() {
        None
    } else {
        Some(positions)
    }
}

// 簡易JSONパーサーとシリアライザー（外部ライブラリ不使用のため）
mod serde_json {
    use std::collections::HashMap;

    pub fn from_str<T: std::str::FromStr>(s: &str) -> Result<Vec<T>, ()> {
        let trimmed = s.trim();
        if !trimmed.starts_with('[') || !trimmed.ends_with(']') {
            return Err(());
        }
        let inner = &trimmed[1..trimmed.len()-1];
        let mut items = Vec::new();
        for part in inner.split(',') {
            let part = part.trim().trim_matches('"');
            if let Ok(v) = part.parse::<T>() {
                items.push(v);
            } else {
                return Err(());
            }
        }
        Ok(items)
    }

    pub fn to_string<T: std::fmt::Display>(value: &T) -> String {
        format!("{}", value)
    }

    pub fn to_string_map(map: &HashMap<String, Vec<usize>>) -> String {
        let mut result = String::from("{");
        for (i, (k, v)) in map.iter().enumerate() {
            if i > 0 { result.push(','); }
            result.push('"');
            result.push_str(k);
            result.push_str("\":[");
            for (j, val) in v.iter().enumerate() {
                if j > 0 { result.push(','); }
                result.push_str(&val.to_string());
            }
            result.push(']');
        }
        result.push('}');
        result
    }
}
