fn process_attributes(text: &str) -> Result<Value, String> {
    let mut attributes = std::collections::HashMap::new();
    let mut sep: Option<char> = None;
    let text_trimmed = text.trim();

    for c in text_trimmed.chars() {
        if c == '=' || c == ' ' {
            sep = Some(c);
            break;
        }
    }

    if sep.is_none() {
        return Err(format!("Your GFF/GTF does not seem to be correct ({}). Expected a = or space as separator", text));
    }

    let mut text = text_trimmed.to_string();
    text = text.replace("%09", "\t").replace("%0A", "\n").replace("%0D", "\r");
    text = text.replace("%25", "%").replace("%3D", "=").replace("%26", "&").replace("%2C", ",");
    text = text.replace("%28", "(").replace("%29", ")");

    let pattern = Regex::new(r#"(\S+?)[= ](".*?"|[^;]*)(?:;|$)"#).unwrap();
    let mut parsed = std::collections::HashMap::new();

    for cap in pattern.captures_iter(&text) {
        let key = cap.get(1).unwrap().as_str().to_string();
        let value = cap.get(2).unwrap().as_str().trim_matches('"').to_string();
        parsed.insert(key, value);
    }

    let mut result = serde_json::Map::new();
    for (k, v) in parsed {
        result.insert(k, Value::String(v));
    }
    Ok(Value::Object(result))
}

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).expect("Failed to read input");

    let args: Value = serde_json::from_str(&input).expect("Invalid JSON input");
    let text = args[0].as_str().unwrap_or("");

    match process_attributes(text) {
        Ok(result) => println!("{}", result),
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}
