実装方針: 入力のJSON配列から`params`と`record`を取得し、`record`がベクトルならL2ノルムでクリッピングし、スカラーならそのまま返す関数を実装します。

```rust
use std::io::{self, Read};
use std::collections::BTreeMap;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let input = input.trim();

    // JSON配列をパースする簡易実装
    let (value, _) = parse_json(input);

    // 引数は配列で、[params, record] の形式
    if let JsonValue::Array(args) = value {
        if args.len() >= 2 {
            let params = &args[0];
            let record = &args[1];

            // recordが配列（ベクトル）の場合、L2ノルムでクリッピング
            if let JsonValue::Array(vec) = record {
                // ベクトルの要素を数値として取得
                let mut nums: Vec<f64> = Vec::new();
                for item in vec {
                    if let JsonValue::Number(n) = item {
                        nums.push(n);
                    } else {
                        // 数値でない場合はそのまま返す（エラー回避）
                        print_json(record);
                        return;
                    }
                }

                // paramsからクリッピングノルムを取得（数値であると仮定）
                let clip_norm = match params {
                    JsonValue::Number(n) => n,
                    _ => 1.0, // デフォルト
                };

                // L2ノルム計算
                let l2_norm: f64 = nums.iter().map(|x| x * x).sum::<f64>().sqrt();

                if l2_norm > clip_norm && l2_norm > 0.0 {
                    let scale = clip_norm / l2_norm;
                    let clipped: Vec<f64> = nums.iter().map(|x| x * scale).collect();
                    print_json(&JsonValue::Array(clipped.into_iter().map(JsonValue::Number).collect()));
                } else {
                    print_json(record);
                }
            } else {
                // ベクトルでない場合はそのまま返す
                print_json(record);
            }
        } else {
            println!("null");
        }
    } else {
        println!("null");
    }
}

// 簡易JSONパーサー
#[derive(Debug, Clone)]
enum JsonValue {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<JsonValue>),
    Object(BTreeMap<String, JsonValue>),
}

fn parse_json(s: &str) -> (JsonValue, usize) {
    let s = s.trim_start();
    match s.chars().next() {
        Some('n') => (JsonValue::Null, 4),
        Some('t') => (JsonValue::Bool(true), 4),
        Some('f') => (JsonValue::Bool(false), 5),
        Some('"') => {
            let end = s[1..].find('"').unwrap() + 1;
            (JsonValue::String(s[1..end].to_string()), end + 1)
        }
        Some('[') => {
            let mut i = 1;
            let mut arr = Vec::new();
            loop {
                let (val, consumed) = parse_json(&s[i..]);
                arr.push(val);
                i += consumed;
                let rest = s[i..].trim_start();
                if rest.starts_with(',') {
                    i += 1;
                } else if rest.starts_with(']') {
                    i += 1;
                    break;
                } else {
                    break;
                }
            }
            (JsonValue::Array(arr), i)
        }
        Some('{') => {
            let mut i = 1;
            let mut obj = BTreeMap::new();
            loop {
                let (key, consumed) = parse_json(&s[i..]);
                i += consumed;
                let rest = s[i..].trim_start();
                if rest.starts_with(':') {
                    i += 1;
                    let (val, consumed2) = parse_json(&s[i..]);
                    if let JsonValue::String(k) = key {
                        obj.insert(k, val);
                    }
                    i += consumed2;
                }
                let rest2 = s[i..].trim_start();
                if rest2.starts_with(',') {
                    i += 1;
                } else if rest2.starts_with('}') {
                    i += 1;
                    break;
                } else {
                    break;
                }
            }
            (JsonValue::Object(obj), i)
        }
        Some(c) if c.is_digit(10) || c == '-' => {
            let end = s.find(|c: char| !c.is_digit(10) && c != '.' && c != '-' && c != 'e' && c != 'E' && c != '+' && c != '-').unwrap_or(s.len());
            let num: f64 = s[..end].parse().unwrap_or(0.0);
            (JsonValue::Number(num), end)
        }
        _ => (JsonValue::Null, 1),
    }
}

fn print_json(v: &JsonValue) {
    match v {
        JsonValue::Null => print!("null"),
        JsonValue::Bool(b) => print!("{}", b),
        JsonValue::Number(n) => {
            if n.fract() == 0.0 {
                print!("{}", *n as i64);
            } else {
                print!("{}", n);
            }
        }
        JsonValue::String(s) => print!("\"{}\"", s),
        JsonValue::Array(arr) => {
            print!("[");
            for (i, item) in arr.iter().enumerate() {
                if i > 0 { print!(","); }
                print_json(item);
            }
            print!("]");
        }
        JsonValue::Object(obj) => {
            print!("{{");
            for (i, (k, val)) in obj.iter().enumerate() {
                if i > 0 { print!(","); }
                print!("\"{}\":", k);
                print_json(val);
            }
            print!("}}");
        }
    }
}
