fn add_key(args: Value) -> Value {
    // 引数の数を確認
    if !args.is_array() || args.as_array().unwrap().len() != 5 {
        return json!(null);
    }

    let base = &args[0];
    let new = &args[1];
    let base_name = &args[2];
    let new_name = &args[3];
    let device = &args[4];

    // 型チェック
    if !base.is_array() {
        panic!("ValueError: base must be a tensor (array)");
    }
    if !base_name.is_string() {
        panic!("ValueError: base_name must be a string");
    }
    if !new_name.is_string() {
        panic!("ValueError: new_name must be a string");
    }
    if !device.is_null() && !device.is_string() {
        panic!("ValueError: device must be null or a string");
    }

    // newが辞書の場合のみ処理
    if new.is_object() {
        // deviceが指定されている場合は各値を変換（ここでは単純にそのまま）
        if !device.is_null() {
            // 実際のテンソル変換はできないため、値はそのまま
        }
        // 辞書を構築
        let mut result = serde_json::Map::new();
        result.insert(base_name.as_str().unwrap().to_string(), base.clone());
        result.insert(new_name.as_str().unwrap().to_string(), new.clone());
        return Value::Object(result);
    } else {
        // newがnullまたは辞書でない場合はbaseをそのまま返す
        return base.clone();
    }
}
