fn lint(source: &str, strict: bool) -> Vec<String> {
    let doc = match load_doc(source) {
        Ok(d) => d,
        Err(e) => return vec![format!("[LOAD ERROR] {}", e)],
    };

    let mut errors = Vec::new();
    let collection_id = doc.get("id").and_then(|v| v.as_str()).unwrap_or(source);

    if let Some(assets) = doc.get("assets").and_then(|v| v.as_object()) {
        for (asset_key, asset) in assets {
            let mime = asset.get("type").and_then(|v| v.as_str()).unwrap_or("");
            if !mime.contains("pmtiles") {
                continue;
            }

            let vlayers = asset.get("vector:layers");
            if vlayers.is_none() || vlayers.and_then(|v| v.as_array()).map_or(true, |a| a.is_empty()) {
                errors.push(format!("[{}] asset '{}': PMTiles asset missing 'vector:layers' (the MapLibre source-layer id(s)).", collection_id, asset_key));
            }

            let columns = asset.get("table:columns").and_then(|v| v.as_array());
            if columns.is_none() || columns.map_or(true, |a| a.is_empty()) {
                errors.push(format!("[{}] asset '{}': PMTiles asset has empty 'table:columns' — populate the tile-accurate fields from the .pmtiles footer (vector_layers[].fields). See data-workflows #283.", collection_id, asset_key));
                continue;
            }

            if let Some(cols) = columns {
                for col in cols {
                    if let Some(col_obj) = col.as_object() {
                        let name = col_obj.get("name").and_then(|v| v.as_str()).unwrap_or("");
                        if name.is_empty() {
                            errors.push(format!("[{}] asset '{}': a table:columns entry is missing 'name'.", collection_id, asset_key));
                            continue;
                        }
                        if col_obj.get("type").is_none() {
                            errors.push(format!("[{}] asset '{}', column '{}': missing 'type'.", collection_id, asset_key, name));
                        }
                    }
                }
            }
        }
    }

    errors
}

