    io::stdin().read_to_string(&mut input).unwrap();
    let args: Vec<serde_json::Value> = serde_json::from_str(&input).unwrap();
    let source = args[0].as_str().unwrap().to_string();
    let strict = args.get(1).and_then(|v| v.as_bool()).unwrap_or(false);

    let result = lint(&source, strict);
